// SCRUM-906 staging proof harness (the whole BEO kitchen plan reaches the till), as run on 12 November 2026 against
// oto-app-staging dep-dbqri2rbc2fs73e7s29g, oto-api-staging dep-dbqrjnbbc2fs73e80610, oto-pos-web-staging
// dep-dbqrm8dckfvc73d9upg0 and oto-pos-staging dep-dbqrm8gn74is73d22drg, all at f17359759 (deploys.json "before"); the
// api and both tills moved to 963605c97 (contains it) at 13:41-13:44 UTC, during point 5 (deploys.json "after").
// One file: every script of the run as text; `node proof.mjs <folder>` writes them out. The driver keeps ONE headless
// Chromium open and runs one step file per request (node go.mjs steps/<file>), appending each step and its scrubbed
// answer to steps.log beside this file. Credentials by NAME only through scripts/agent/env.mjs need(); staff names
// held in memory for masking only (raw/names.txt in the scratch folder for the name checks, never committed).
// The run, in order (UTC), as steps.log records it:
//   deploys.mjs deploys.json before (13:16) | 01-look | 03-health | 04-release | 02-setup (ZZ TEST till Z90601, five
//   ZZ TEST simulated printers on Virtual box 1) | 05-party1 | 06-parent | 07-tillread | 08-desk | 09-shotfix |
//   10-beo-side | 11-phone | 12-phone-retake-and-parent-before | 13-staff-change | 14-refresh-wait (failed on a locked
//   till) | 16-inspect | 17-refresh-again | 15-party2 | 18-slips-print | 19-slips-change | 19b-slips-change-both (first
//   try stopped on the bar quantity field before any save; fixed and run) | 26-station-back | 20-settle-open (refused
//   STOCK_SHORT, socks) | 20x-inspect | 20-settle-open again (refusal recorded) | 20b-settle-open-socks0 |
//   21-phone-open-then-pay | 22-refund | 22b-tax | 23-pdf (pdf_render.py renders it) | 24-bigqty | 25-package-only |
//   25b-bigqty-packaged | 03-health | 04-release | 27-release-picture | 28-p2-slips-now | 30-cleanup | 31-signout |
//   POST /quit | deploys.mjs deploys.json after | scrubfile.mjs | finalize.mjs | namecheck.mjs.
// Picture edits after the run: the band codes on 05f and 05g blacked out (PyMuPDF); 01k removed (a duplicate of 01j);
// no picture kept of the first staff change on the tills (the step stopped on the locked till); 05c/05d renamed 05d1-05d3.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
const FILES = {
 "driver.mjs": "// SCRUM-906 staging proof driver (the whole BEO kitchen plan reaches the till), 12 November 2026.\n// An interactive driver, as the SCRUM-909 run was driven: ONE headless Chromium kept open, one step at a time. Each\n// step is sent to a local port (127.0.0.1 only) as a small async body that gets the state object S; every step and its\n// answer are appended to steps.log beside the receipt (scrubbed), so the run can be read back in the order it was driven.\n// Started from the SCRUM-909 driver (own ZZ TEST till, the party page, Settle party, cash, a manager's refund), the\n// SCRUM-861 harness (ZZ TEST kitchen and bar printers on Virtual box 1, the slips read back as printouts and print\n// jobs) and the SCRUM-905 harness (a ZZ TEST party in the OTO App through the launcher, the parent link's public routes).\n//\n//   node driver.mjs [port]      then  POST http://127.0.0.1:<port>/run  with the step's body;  POST /quit  ends it.\n//\n// ZZ TEST records only. Cash only. Credentials are read by NAME through scripts/agent/env.mjs need() and never printed;\n// staff names never enter the receipt or the log (scrubbed), and on pictures the account corner, the password field,\n// staff names and other parties are masked.\nimport assert from 'node:assert/strict';\nimport { randomUUID } from 'node:crypto';\nimport { createServer } from 'node:http';\nimport { createRequire } from 'node:module';\nimport { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';\nimport { resolve } from 'node:path';\nimport { pathToFileURL } from 'node:url';\n\nconst repo = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos';\nconst { need } = await import(pathToFileURL(resolve(repo, 'scripts/agent/env.mjs')));\nconst pw = createRequire(resolve(repo, 'apps/pos/package.json'))('@playwright/test');\nconst { chromium, request, expect } = pw;\nconst port = Number(process.argv[2] ?? 47906);\nconst out = resolve(repo, 'docs/qa/proof-2026-11-12/SCRUM-906');\nmkdirSync(out, { recursive: true });\nconst scratch = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p906';\nmkdirSync(resolve(scratch, 'raw'), { recursive: true });\n\nconst S = { pw, expect, assert, randomUUID, resolve, out, scratch, writeFileSync, readFileSync, existsSync };\nS.pos = 'https://oto-pos-web-staging.onrender.com';\nS.LAUNCHER = 'https://oto-launcher-staging.onrender.com';\nS.APP = 'https://oto-app-staging.onrender.com';\nS.APP_FLORESTA = '6427e84d-723f-4dbd-be58-8ef89cf7dc99';\nS.FLORESTA_PACKAGE = '391b269d-159a-4039-89a2-51ac132da747';\nS.today = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Bangkok' }).format(new Date());\nS.bkk = d => new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Bangkok', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).format(new Date(d));\nS.flat = t => String(t ?? '').replace(/\\s+/g, ' ').trim();\nS.ID = /[0-9a-f]{8}-[0-9a-f-]{27}/g;\nS.isZz = s => /^ZZ TEST/i.test(String(s ?? '').trim());\nS.sleep = ms => new Promise(r => setTimeout(r, ms));\nS.receipt = { ticket: 'SCRUM-906', title: 'The whole BEO kitchen plan reaches the till', sha: 'f17359759e3a1afbead09a763aa9eb8560738183',\n  startedAt: new Date().toISOString(), created: [], points: {}, reads: {}, odd: [], pageErrors: [], requests: [], cleanup: {} };\n\n// ---- staff names: memory only, scrubbed from everything written ----\nS.names = new Set();\nS.hidden = []; // other parties' titles and people: memory only\nS.addName = v => { if (typeof v !== 'string') return; const t = v.trim(); if (t.length < 2 || S.isZz(t)) return; S.names.add(t); for (const p of t.split(/\\s+/)) { const w = p.replace(/[()]/g, ''); if (w.length >= 3) S.names.add(w); } };\nconst STOP = /^(ZZ|TEST|SCRUM|proof|till|OTO|Till|Manager|Reception|Admin|Staff|Owner|Khun|Central|Floresta|Party|Kitchen|Bar|Cake|Birthday|package)$/i;\nS.needles = () => [...S.hidden, ...[...S.names].filter(s => s.length >= 3 && !STOP.test(s))].filter(Boolean).sort((a, b) => b.length - a.length);\nS.scrub = text => {\n  let t = String(text);\n  for (const n of S.needles()) t = t.split(n).join('[name]');\n  return t.replace(/[0-9a-f]{48}/g, '<token>');\n};\nS.save = () => writeFileSync(resolve(out, 'receipt.json'), S.scrub(JSON.stringify(S.receipt, null, 2)) + '\\n');\nS.point = (key, pass, pictures, seen) => { S.receipt.points[key] = { verdict: pass ? 'PASS' : 'FAIL', pictures, seen }; S.save(); return { key, pass }; };\nS.odd = (what, extra = {}) => { S.receipt.odd.push({ what, ...extra }); S.save(); };\n\n// ---- the admin api on the till's origin (stations, printers, reads, clean-up) ----\nS.admin = await request.newContext({ baseURL: S.pos });\nconst adminSignIn = async () => assert.equal((await S.admin.post('/api/auth/sign-in', { data: { phone: need('STAGING_ADMIN_PHONE'), password: need('STAGING_ADMIN_PASSWORD') } })).status(), 200);\nS.call = async (method, path, data, headers = {}) => {\n  const once = () => S.admin.fetch(`/api${path}`, { method, ...(data === undefined ? {} : { data }), headers: method === 'GET' ? headers : { 'idempotency-key': randomUUID(), ...headers }, timeout: 120000 });\n  let r = await once();\n  if (r.status() === 401) { await adminSignIn(); r = await once(); }\n  const body = await r.json().catch(() => null);\n  S.receipt.requests.push({ via: 'platform admin', method, path: path.split('?')[0].replace(S.ID, ':id'), status: r.status(), ...(r.status() >= 400 ? { errorCode: body?.error?.code ?? null } : {}) });\n  return { status: r.status(), body };\n};\nawait adminSignIn();\n{\n  const me = (await S.call('GET', '/me')).body;\n  for (const o of [me?.employee, me?.account]) for (const k of ['name', 'nickname']) S.addName(o?.[k]);\n}\nS.branch = (await S.call('GET', '/branches')).body.branches.find(b => /Central Floresta/.test(b.name));\nS.branchId = S.branch.id;\n\n// ---- the browser: one, headless ----\nS.browser = await chromium.launch({ headless: true });\nS.pages = {};\nS.watch = (page, label) => {\n  page.on('pageerror', e => { S.receipt.pageErrors.push({ page: label, at: S.phase ?? null, kind: 'pageerror', text: S.scrub(String(e.message).split('\\n')[0].slice(0, 240)) }); });\n  page.on('console', m => { if (m.type() === 'error') S.receipt.pageErrors.push({ page: label, at: S.phase ?? null, kind: 'console.error', text: S.scrub(m.text().split('\\n')[0].slice(0, 240)) }); });\n  page.on('response', r => { try { const u = new URL(r.url()); if (r.status() >= 400 && /\\/api\\//.test(u.pathname)) S.receipt.pageErrors.push({ page: label, at: S.phase ?? null, kind: 'http', text: `${r.request().method()} ${u.pathname.replace(S.ID, ':id')} ${r.status()}` }); } catch { /* ignore */ } });\n};\nconst walkNames = (o, d = 0) => { if (!o || d > 3) return; for (const [k, v] of Object.entries(o)) { if (typeof v === 'string' && /^(name|nickname|fullName|displayName|firstName|lastName)$/i.test(k)) S.addName(v); else if (v && typeof v === 'object' && !/branch|operator|station|role/i.test(k)) walkNames(v, d + 1); } };\nS.landing = page => page.locator('[data-testid=\"language-choice\"],[data-testid=\"identify-safety\"]').first();\nS.signIn = async (label, phoneKey, passwordKey, viewport, extra = {}) => {\n  const ctx = await S.browser.newContext({ baseURL: S.pos, viewport, timezoneId: 'Asia/Bangkok', locale: 'en-GB',\n    ...(viewport.width < 600 ? { isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : {}), ...extra });\n  ctx.setDefaultTimeout(30000);\n  const page = await ctx.newPage(); S.watch(page, label); await page.goto(S.pos);\n  await page.locator('input[inputmode=\"tel\"],input[type=\"tel\"]').first().fill(need(phoneKey).replace(/^\\+66/, '0'));\n  await page.locator('input[type=\"password\"]').first().fill(need(passwordKey));\n  await page.getByRole('button', { name: 'Sign in', exact: true }).click();\n  const pick = page.getByRole('button', { name: S.fixtureName, exact: false }).first();\n  const picker = page.getByRole('heading', { name: 'Which station are you on?' });\n  const deadline = Date.now() + 60000;\n  while (Date.now() < deadline) { if (await picker.isVisible()) { if (await pick.isVisible()) { await pick.click(); break; } } else if (await page.locator('a[href=\"/history\"]').first().isVisible()) break; await page.waitForTimeout(500); }\n  await page.locator('a[href=\"/history\"], a[href=\"/parties\"]').first().waitFor({ timeout: 60000 });\n  const me = await page.evaluate(async () => (await (await fetch('/api/me', { credentials: 'include' })).json()));\n  walkNames(me);\n  assert.ok(JSON.stringify(me).includes(S.station.id), 'signed in at the own ZZ TEST till');\n  S.pages[label] = { ctx, page, passwordKey };\n  return page;\n};\nS.unlock = async label => {\n  const t = S.pages[label];\n  if (await t.page.getByRole('heading', { name: 'Locked', exact: true }).isVisible().catch(() => false)) {\n    await t.page.locator('input[type=\"password\"]').first().fill(need(t.passwordKey));\n    await t.page.getByRole('button', { name: /Unlock/ }).click(); await t.page.waitForTimeout(3000);\n    return true;\n  }\n  return false;\n};\nS.signOutTill = async label => {\n  const t = S.pages[label];\n  if (!t) return null;\n  const so = await t.page.request.post('/api/auth/sign-out', { headers: { 'idempotency-key': randomUUID() } }).catch(() => null);\n  const me = await t.page.request.get('/api/me').catch(() => null);\n  await t.ctx.close().catch(() => {});\n  delete S.pages[label];\n  return { signOut: so?.status() ?? null, meAfter: me?.status() ?? null };\n};\n\n// ---- the OTO App, through the launcher (the staging administrator) ----\nS.openApp = async () => {\n  if (S.app) return S.app;\n  const ctx = await S.browser.newContext({ viewport: { width: 1440, height: 1000 }, timezoneId: 'Asia/Bangkok', locale: 'en-GB', colorScheme: 'light' });\n  ctx.setDefaultTimeout(30000);\n  assert.equal((await ctx.request.post(S.LAUNCHER + '/api/auth/sign-in', { data: { phone: need('STAGING_ADMIN_PHONE'), password: need('STAGING_ADMIN_PASSWORD') } })).status(), 200);\n  const hand = await (await ctx.request.post(S.LAUNCHER + '/api/auth/handoff', { data: { app: 'oto_app' }, headers: { 'Idempotency-Key': randomUUID() } })).json();\n  const page = await ctx.newPage();\n  S.watch(page, 'oto-app');\n  const exchanged = page.waitForResponse(r => new URL(r.url()).pathname === '/api/auth/handoff', { timeout: 90000 });\n  await page.goto(hand.launchUrl); await exchanged;\n  await page.waitForURL(u => !u.hash.includes('handoff'), { timeout: 60000 }).catch(() => {});\n  S.app = { ctx, page };\n  const u = (await S.appCall('GET', '/user')).body;\n  for (const v of [u?.fullName, u?.firstName, u?.lastName, u?.nickname, u?.displayName, u?.username, u?.name]) S.addName(v);\n  const em = (await S.appCall('GET', `/employees?branchId=${S.APP_FLORESTA}`)).body;\n  for (const e of (Array.isArray(em) ? em : em?.employees ?? [])) { S.addName(e.nickname); S.addName(e.fullName); S.addName(e.thaiName); }\n  return S.app;\n};\nS.appCall = async (method, path, body) => {\n  const r = await S.app.ctx.request.fetch(S.APP + '/api' + path, { method, data: body, headers: method === 'GET' ? {} : { 'Idempotency-Key': randomUUID() }, timeout: 120000 });\n  const text = await r.text();\n  let b = null; try { b = JSON.parse(text); } catch { b = text.slice(0, 300); }\n  S.receipt.requests.push({ via: 'oto app', method, path: path.split('?')[0].replace(S.ID, ':id').replace(/[0-9a-f]{48}/g, '<token>'), status: r.status() });\n  return { status: r.status(), body: b };\n};\nS.hideBoard = page => page.evaluate(() => { const root = document.getElementById('root'); if (!root) return false; root.setAttribute('data-board-hidden', '1'); root.style.visibility = 'hidden'; root.style.opacity = '0'; return true; });\nS.showBoard = page => page.evaluate(() => { const root = document.querySelector('[data-board-hidden]'); if (root) { root.style.visibility = ''; root.style.opacity = ''; root.removeAttribute('data-board-hidden'); } });\n\n// ---- pictures: names blacked out in place; structural masks; nothing else touched ----\nS.otherParties = page => page.locator('div.space-y-2 > button.w-full').filter({ hasNotText: 'ZZ TEST' });\nS.otherSales = page => page.locator('div.space-y-2 > button.w-full.text-left:not([data-zz]):not([role=\"dialog\"] *)');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nS.masks = page => [page.locator('input[type=\"password\"]'), page.getByTestId('display-pairing-code'), page.locator('canvas'), page.getByText(/^QR-[A-Z0-9]+$/)];\nS.shots = [];\nS.shot = async (page, name, extra = [], opts = {}) => {\n  for (const loc of S.inPlace(page)) await loc.evaluateAll(els => { for (const e of els) e.setAttribute('data-zz-mask', '1'); }).catch(() => {});\n  await page.evaluate((list) => {\n    if (!document.getElementById('zz-mask-style')) { const st = document.createElement('style'); st.id = 'zz-mask-style'; st.textContent = '[data-zz-mask]{background:#18181b!important;color:#18181b!important;border-color:#18181b!important;border-radius:2px} [data-zz-mask] *{color:#18181b!important;background:#18181b!important}'; document.head.appendChild(st); }\n    const esc = s => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    const res = list.map(s => new RegExp(`(?<![\\\\p{L}\\\\p{N}])${esc(s)}(?![\\\\p{L}\\\\p{N}])`, 'iu'));\n    const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    while (w.nextNode()) { const v = w.currentNode.nodeValue || ''; if (v.trim() && res.some(r => r.test(v))) w.currentNode.parentElement?.setAttribute('data-zz-mask', '1'); }\n    for (const el of document.querySelectorAll('input,textarea')) { if (res.some(r => r.test(el.value || ''))) el.setAttribute('data-zz-mask', '1'); }\n  }, S.needles());\n  try {\n    if (opts.element) await opts.element.screenshot({ path: resolve(out, name), animations: 'disabled', mask: [...S.masks(page), ...extra], maskColor: '#18181b' });\n    else await page.screenshot({ path: resolve(out, name), animations: 'disabled', ...opts, mask: [...S.masks(page), ...extra], maskColor: '#18181b' });\n  } finally {\n    await page.evaluate(() => { for (const el of document.querySelectorAll('[data-zz-mask]')) el.removeAttribute('data-zz-mask'); }).catch(() => {});\n  }\n  S.shots.push(name);\n  return name;\n};\n\n// ---- the simulated printers: what each drew ----\nS.printouts = async role => {\n  const dev = S.devices[role];\n  const r = await S.call('GET', `/devices/${dev.id}/printouts?limit=20`);\n  return r.status === 200 ? r.body.printouts : [];\n};\nS.keyOf = p => `${p.seq}@${p.at}`;\nS.keepPreview = async (role, p, name, dir = out) => {\n  const r = await S.admin.get(`/api/devices/${S.devices[role].id}/printouts/${p.seq}/preview.png`);\n  assert.equal(r.status(), 200, 'preview read');\n  writeFileSync(resolve(dir, name), await r.body());\n  return name;\n};\nS.jobsAtTill = async (sinceIso) => (await S.call('GET', `/branches/${S.branchId}/print-jobs?stationId=${S.station.id}&limit=200`)).body.jobs\n  .filter(j => !sinceIso || Date.parse(j.queuedAt) >= Date.parse(sinceIso))\n  .sort((a, b) => Date.parse(a.queuedAt) - Date.parse(b.queuedAt))\n  .map(j => ({ queuedAt: j.queuedAt, bangkok: S.bkk(j.queuedAt), kind: j.kind, role: j.role, printer: j.deviceLabel, status: j.status, reprintOf: j.reprintOf ? 'copy' : null, errorCode: j.errorCode }));\nS.auditOf = async (action, entityId) => ((await S.call('GET', `/audit?action=${encodeURIComponent(action)}&entityId=${entityId}&limit=50`)).body?.entries ?? []);\nS.party = async id => (await S.call('GET', `/parties/${id}?branchId=${S.branchId}`));\nS.sale = async id => (await S.call('GET', `/sales/${id}`)).body;\nS.stationSales = async () => (await S.call('GET', `/sales?branchId=${S.branchId}&stationId=${S.station.id}&limit=50`)).body.sales;\n\n// ---- the step server ----\nconst AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;\nconst log = resolve(out, 'steps.log');\nlet busy = false;\nconst server = createServer((req, res) => {\n  let body = '';\n  req.on('data', c => { body += c; });\n  req.on('end', async () => {\n    if (req.url === '/quit') { res.end('bye'); await S.browser?.close().catch(() => {}); await S.admin.dispose().catch(() => {}); server.close(); process.exit(0); }\n    if (busy) { res.statusCode = 409; res.end('busy'); return; }\n    busy = true;\n    const at = new Date().toISOString();\n    let answer;\n    try {\n      const value = await new AsyncFunction('S', body)(S);\n      answer = { ok: true, value };\n    } catch (error) {\n      answer = { ok: false, error: `${error?.name ?? 'Error'}: ${String(error?.message ?? error).split('\\n').slice(0, 8).join(' | ').slice(0, 1500)}` };\n    }\n    busy = false;\n    const text = S.scrub(JSON.stringify(answer, null, 1));\n    appendFileSync(log, `\\n=== ${at} ${S.phase ?? ''}\\n${body.trim()}\\n--> ${text.slice(0, 6000)}\\n`);\n    S.save();\n    res.setHeader('content-type', 'application/json');\n    res.end(text);\n  });\n});\nserver.listen(port, '127.0.0.1', () => console.log(`driver ready on 127.0.0.1:${port}`));\n",
 "go.mjs": "// Send one step file's body to the driver: node go.mjs <step file> [port]\nimport { readFileSync } from 'node:fs';\nconst [file, port = '47906'] = process.argv.slice(2);\nconst body = readFileSync(file, 'utf8');\nconst r = await fetch(`http://127.0.0.1:${port}/run`, { method: 'POST', body, signal: AbortSignal.timeout(1_500_000) });\nconst t = await r.text();\nconsole.log(t.slice(0, 12000));\n",
 "deploys.mjs": "// READ-ONLY. The four *-staging deploys of SCRUM-906 and what each serves now. Never prints the key; only *-staging.\n// node deploys.mjs <out.json> [tag]\nimport { writeFileSync, existsSync, readFileSync } from 'node:fs';\nimport { need } from 'file:///C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/scripts/agent/env.mjs';\nconst headers = { authorization: `Bearer ${need('RENDER_API_KEY')}`, accept: 'application/json' };\nconst get = async (path) => { const r = await fetch('https://api.render.com/v1' + path, { headers, signal: AbortSignal.timeout(60000) }); return r.ok ? r.json() : { _status: r.status }; };\nconst names = ['oto-app-staging', 'oto-api-staging', 'oto-pos-web-staging', 'oto-pos-staging'];\nconst services = (await get('/services?limit=50')).map((r) => r.service ?? r).filter((s) => /-staging$/.test(s.name));\nconst out = process.argv[2];\nconst tag = process.argv[3] ?? 'read';\nconst state = existsSync(out) ? JSON.parse(readFileSync(out, 'utf8')) : {};\nconst snap = { readAt: new Date().toISOString(), services: {} };\nfor (const name of names) {\n  const s = services.find((x) => x.name === name);\n  if (!s) { snap.services[name] = null; continue; }\n  const list = (await get(`/services/${s.id}/deploys?limit=5`)).map((x) => x.deploy ?? x);\n  const live = list.find((x) => x.status === 'live');\n  snap.services[name] = {\n    live: live ? { id: live.id, sha: live.commit?.id, createdAt: live.createdAt, finishedAt: live.finishedAt, trigger: live.trigger ?? null } : null,\n    latest: list[0] ? { id: list[0].id, status: list[0].status, sha: list[0].commit?.id } : null,\n  };\n}\nstate[tag] = snap;\nwriteFileSync(out, JSON.stringify(state, null, 2) + '\\n');\nconsole.log(JSON.stringify(snap, null, 1));\n",
 "pdf_render.py": "# Render the ZZ TEST BEO PDF's pages to PNG (scratch) and report the lines that carry a price; count held names.\n# python -I pdf_render.py <pdf> <outdir> <names.txt>\nimport sys, re, json, pathlib\nimport pymupdf\npdf, outdir, names_file = sys.argv[1], pathlib.Path(sys.argv[2]), sys.argv[3]\ndoc = pymupdf.open(pdf)\nnames = [n.strip() for n in open(names_file, encoding='utf-8').read().split('\\n') if len(n.strip()) >= 3]\nout = {'pages': doc.page_count, 'priceLines': [], 'nameHits': 0, 'files': []}\nfor i, page in enumerate(doc):\n    text = page.get_text()\n    for line in text.split('\\n'):\n        if '฿' in line or 'each' in line.lower() or 'EXTRA' in line:\n            out['priceLines'].append({'page': i + 1, 'line': line.strip()})\n    for n in names:\n        if re.search(r'(?<![A-Za-z])' + re.escape(n) + r'(?![A-Za-z])', text, re.I if len(n) > 4 else 0):\n            out['nameHits'] += 1\n    pix = page.get_pixmap(dpi=110)\n    f = outdir / f'beo-p1-page{i + 1}.png'\n    pix.save(str(f))\n    out['files'].append(str(f))\nprint(json.dumps(out, ensure_ascii=False, indent=1))\n",
 "namecheck.mjs": "// Counts held staff names (and token- or phone-like strings) in files; never prints a name. node namecheck.mjs <file>...\nimport { readFileSync } from 'node:fs';\nconst names = readFileSync('C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p906/raw/names.txt', 'utf8').split('\\n').map((s) => s.trim()).filter((s) => s.length >= 3);\nconst esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nfor (const f of process.argv.slice(2)) {\n  const t = readFileSync(f, 'utf8');\n  const hits = names.filter((n) => new RegExp('(?<![A-Za-z])' + esc(n) + '(?![A-Za-z])', n.length <= 4 ? '' : 'i').test(t));\n  console.log(f.split(/[\\\\/]/).pop(), 'name hits', hits.length, 'lengths', hits.map((h) => h.length).join(','), 'token-like', /[0-9a-f]{48}/.test(t), 'phone-like', /(\\+66|\\b0)[689]\\d{8}\\b/.test(t));\n}\n",
 "scrubfile.mjs": "// Replace held staff names in files with [name] (word-bounded; names of 4 letters or fewer case-sensitive). Prints counts only.\nimport { readFileSync, writeFileSync } from 'node:fs';\nconst names = readFileSync('C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p906/raw/names.txt', 'utf8').split('\\n').map((s) => s.trim()).filter((s) => s.length >= 3).sort((a, b) => b.length - a.length);\nconst esc = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nfor (const f of process.argv.slice(2)) {\n  let t = readFileSync(f, 'utf8'); let n = 0;\n  for (const name of names) t = t.replace(new RegExp('(?<![A-Za-z])' + esc(name) + '(?![A-Za-z])', name.length <= 4 ? 'g' : 'gi'), () => { n += 1; return '[name]'; });\n  writeFileSync(f, t); console.log(f.split(/[\\\\/]/).pop(), 'replaced', n);\n}\n",
 "finalize.mjs": "// Adds the verdicts, the deploy note, the pictures and the findings to docs/qa/proof-2026-11-12/SCRUM-906/receipt.json\n// (the driver wrote the read-backs). node finalize.mjs\nimport { readFileSync, writeFileSync, readdirSync } from 'node:fs';\nconst DIR = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/docs/qa/proof-2026-11-12/SCRUM-906/';\nconst r = JSON.parse(readFileSync(DIR + 'receipt.json', 'utf8'));\nconst pics = readdirSync(DIR).filter((f) => f.endsWith('.png')).sort();\nconst d = JSON.parse(readFileSync(DIR + 'deploys.json', 'utf8'));\nr.deploys = {\n  file: 'deploys.json (before: all four live at f17359759; after: api, pos-web and pos at 963605c97)',\n  before: Object.fromEntries(Object.entries(d.before.services).map(([k, v]) => [k, `${v.live.id} ${v.live.sha.slice(0, 9)} live ${v.live.finishedAt}`])),\n  after: Object.fromEntries(Object.entries(d.after.services).map(([k, v]) => [k, `${v.live.id} ${v.live.sha.slice(0, 9)} live ${v.live.finishedAt}`])),\n  note: 'Points 1 to 4 and point 6 (13:16-13:42 UTC) ran with all four services at f17359759. During point 5 another deploy went live: oto-pos-staging 13:41:05Z, oto-pos-web-staging 13:43:22Z, oto-api-staging 13:44:52Z, all at 963605c97, which contains f17359759 and adds POS money/party-bill/history changes (PartyDetail, MobilePartyDetail, usePartyPlanRead, partySettlementBill, PartySettleModal) and, in the api, only a sale supervision gate (services/sale.ts). The settlement (13:46), refund (13:48), points 8 and 9 (13:49-13:50) therefore ran on 963605c97 tills and api; whether each open page had loaded the new bundle was not checked. The OTO App stayed at f17359759 throughout.',\n};\nconst P = (verdict, pictures, facts) => ({ verdict, pictures, facts });\nr.points = {\n  '1 the whole plan on the till (party WITH package)': P('PASS',\n    ['01a', '01b', '01c', '01d', '01e', '01f', '01g', '01h', '01i', '01j'],\n    'GET /api/parties/:id (till origin) 200, planStatus ready, kitchenPlan: the 8 set-menu lines named with their group (Pizza: Margherita, Hot dish: Chicken schnitzel, French fries, Waffles or pancakes: Waffles, Fried rice: Veggie, Veggie sticks, Fruit skewers [not on till], Drinks pitcher: Juice [not on till]); Calamari x2 entered 120 (CF-14); Hummus x1 no price (CF-13); ZZ TEST mango sticky rice x2 entered 90 [not on till]; ZZ TEST fruit plate x1 [not on till]; bar: Fresh cold pressed orange juice x4 SET (CF-63-1), Mineral water x2 EXTRA (CF-65-6), ZZ TEST lemonade pitcher x2 [not on till]; bar service 19:15; cake our x1 20:30 \"ZZ TEST unicorn\". Desk and phone pages show every line, the hand-typed ones marked \"not on the till menu\", the cake row \"Our cake x1 · 20:30 / ZZ TEST unicorn\". The page writes a chosen dish \"Pizza · Margherita\" (the slip writes \"Pizza: Margherita\"). The entered prices were written through the BEO save route (PUT /api/events/:id/beo): the editor has no price box on kitchen or bar lines.'),\n  '2 a staff choice after the parent\\'s': P('PASS',\n    ['02a', '02b', '02c', '02d', '02e'],\n    'Parent chose Fried rice: Veggie through the link (submit 200). Staff renamed the resolved line in the BEO editor and saved (PUT 200): the till api answered \"Fried rice: Chicken\" 1.3 s later. Open pages left alone: both tills had LOCKED after 2 minutes idle (the till\\'s inactivity lock) and showed nothing; after unlock the desk showed Chicken at once. Second change Chicken -> Shrimp with the tills kept awake (a Shift key every 25 s, no click, no focus): desk showed Shrimp 34 s after the save, phone 52 s. The parent\\'s link page (reloaded) lists \"Fried rice: Shrimp\"; GET public link selections say the same. Later Shrimp -> Chicken again for point 4.'),\n  '3 a party with NO package': P('PASS',\n    ['03a', '03b'],\n    'GET /api/parties/:id 200, planStatus no_package, kitchenPlan: ZZ TEST nuggets plate x3 [not on till], French fries x1 (CF-11), bar Mineral water x2, cake own 17:00 \"ZZ TEST family cake\". Desk page: no Package row, cake row \"Customer brings their own · 17:00\", bar plan; the buttons are Edit party, Add tickets, Add F&B to party, Fully paid (no Settle party). POST /api/parties/:id/settle/preview 409 PARTY_NO_PACKAGE \"This party has no package in the OTO App, so it cannot be settled here\".'),\n  '4 slips on the ZZ TEST till': P('PASS',\n    ['04a', '04b', '04c', '04d', '04e', '04f', '04g', '04h', '04i'],\n    'Park named no party slips station at start; the ZZ TEST till named 20:29:30-20:42:15 Bangkok. One full job tick with it named printed nothing. \"Print party slips now\" (POST /api/parties/:id/slips/print 200): 1 kitchen + 1 bar job, printed. Kitchen slip: every kitchen line incl. Fruit skewers, Drinks pitcher: Juice, ZZ TEST mango sticky rice and ZZ TEST fruit plate marked \"not on the till menu\", and \"1x Our Cake / Cake time 20:30 · ZZ TEST unicorn\". Bar slip: 4x Fresh cold pressed orange juice, 2x Mineral water, 2x ZZ TEST lemonade pitcher (not on the till menu). Change A (fruit plate 1 -> 2, kitchen only): one kitchen UPDATED slip 54 s after the save (13:31:45 -> 13:32:39 UTC), no VOID (by the SCRUM-861 rule a VOID lists only what a station lost), nothing at the bar, nothing later. Change B (Fried rice Shrimp -> Chicken and lemonade 2 -> 1, one save): kitchen VOID \"1x Fried rice: Shrimp\" + UPDATED, bar VOID \"1x ZZ TEST lemonade pitcher\" + UPDATED, drawn by the simulated printers 24 s after the save (13:39:15 -> 13:39:39-40 UTC), nothing on two later ticks. Print record at the till: 7 jobs, all printed. Audit: party.slips_print 1 (reprint, our till), party.slips_change 2 (run 1 kitchen updated; run 2 kitchen void+updated, bar void+updated).'),\n  '5 settlement and refund': P('PASS',\n    ['05a', '05b', '05c', '05d1', '05d2', '05d3', '05e', '05f', '05g', '05h', '05i'],\n    'Settle preview and sale Z90601-000001: Birthday package 16,900; Calamari 2 x 120 = 240 (entered price); Hummus 1 x 275 = 275 (till price, no entered price); ZZ TEST mango sticky rice 2 x 90 = 180 (typed, entered price); Mineral water 2 x 60 = 120 (bar EXTRA, till price); ZZ TEST fruit plate and ZZ TEST lemonade pitcher (typed, no price) not charged; cake not charged; set-menu lines not charged. Total 17,715 (VAT incl. 1,158.93; extras taxed fnb). First Confirm refused 409 STOCK_SHORT \"Regular Socks is out of stock. Nothing was saved.\" (the form defaults socks given to the kids; staging has 0 socks) - socks set to 0, then settled; cash 17,715, finalised. Manager refund whole from History (Service recovery): 200, refunded 17,715, sale refunded, settlement state refunded; the party page reads as before settlement (Settle party offered, bill 0).'),\n  '6 the release': P('PASS (behaviour) / FAIL (counts on the Health page)',\n    ['06a'],\n    'GET /api/ops/health job:parties.slips: status ok, last outcome ok, every 60 s - but NO counts (notCaughtUp, changesRebased): the register gives status only, and the Console Health page draws the same; the counts are kept only in the run record, which no api returns for an ok run (not read: no database access). Through the api: audit party.slips_schedule_start 2 rows at 20:13:34-35 (both parks, startedAt 13:13:33Z = the first tick after the api went live 13:11:38Z); party.slips_rebase 1 row 20:13:36 at Central Floresta (a party printed before the release; nothing printed for it); no kitchen or bar job at either park from 13:11Z until this run\\'s own press (20:30); party 2 (no package, 11:00) never printed by the schedule while the ZZ TEST till was named (no slip records, no print audit).'),\n  '7 the BEO PDF': P('PASS',\n    ['07a', '07b'],\n    'GET /api/events/:id/beo/pdf 200 application/pdf, 2 pages: \"2x Calamari EXTRA 120฿ each\", \"2x ZZ TEST mango sticky rice EXTRA 90฿ each\"; Hummus, fruit plate, Mineral water, lemonade show EXTRA with no price; \"Expected total (from the till): ฿17,715\"; no staff name in its text.'),\n  '8 a very large quantity': P('PASS',\n    ['08a', '08b', '08c'],\n    'Party 2 (no package): ZZ TEST nuggets plate saved as 250000 (PUT 200): the till api and page show the whole plan with \"x250000\"; party 3 (with package): a typed line of 250000 added - planStatus ready, plan present, every line shown, settle preview 200 (total 16,900, the unpriced typed line not charged).'),\n  '9 nothing else moved': P('PASS',\n    ['09a', '09b', '09c', '09d'],\n    'Party 3, package only: the till shows the package, the eight set-menu groups with no counts and the Included box, as SCRUM-909\\'s 05a showed before this lane; the only difference is \"Fruit skewers · not on the till menu\" (the new mark for an uncoded line). Settle preview: package 16,900 only. SCRUM-916 on party 1 while its settlement was open: desk bill \"Settlement open ฿17715 to take / Outstanding ฿17715\", buttons Resume settlement ฿17715, Cancel settlement, Take balance ฿17715, no Fully paid; phone \"DUE ฿17715\", button \"Settlement open · ฿17715\" disabled, no Fully paid.'),\n};\nr.findings = [\n  'D1 (prices, BEO vs bill): the BEO editor has no price box on kitchen or bar lines (beo-event-editor.tsx, SCRUM-822 removed it), so an \"entered price\" can only come from the till-menu pick, AI fill or the api; staff cannot type 120 or see it on the editor. The editor shows no price for any line, the PDF shows \"120฿ each\" only where a price was entered, and EXTRA lines with no entered price (Hummus, Mineral water) are charged at the till price (275, 2 x 60) with no figure anywhere on the BEO but its expected total.',\n  'D2 (settle form): the Settle party form lumps every BEO EXTRA into one \"Add-ons ฿815\" row (PartySettleModal.tsx QuoteSummary): Calamari, Hummus, mango sticky rice and water are named only on the sale in History and on the receipt.',\n  'D3 (bar slip time): the bar slip prints READY BY 19:10 (kids\\' food 19:30 less 20 min, partyReadyBy in packages/shared/src/party-slips.ts, from SCRUM-805) while the till page and the BEO now show \"Bar service 19:15\".',\n  'D4 (kitchen slip): the set menu\\'s uncoded \"Drinks pitcher: Juice\" prints on the KITCHEN slip (by design until coded; open owner question 9).',\n  'D5 (refresh): a till left idle locks after 2 minutes (auth/timings.ts INACTIVITY_TIMEOUT_MS 120000); a BEO change is not seen behind the lock; an awake till showed it within 34 s (desk) and 52 s (phone).',\n  'D6 (pre-existing): before settlement the desk shows a disabled \"Fully paid\" button and the phone header \"Fully paid\" for a party whose package is unpaid (bill reads ฿0); also on the package-only party at 13:50 on the 963605c97 tills.',\n  'D7 (pre-existing): the BEO PDF prints a set-menu dish as \"Margherita ((Pizza))\" - doubled brackets (apps/oto-app/server/pdf.ts:722 wraps the \"(Pizza)\" note in brackets again).',\n  'D8 (staging data): Settle party defaults \"Socks given\" to the children, and Central Floresta has 0 Regular Socks on staging, so Confirm is refused STOCK_SHORT until socks are set to 0.',\n  'D9 (cosmetic): in the BEO editor a quantity of 250000 overlaps the + button.',\n  'D10 (claim vs product): the plan (State 20:04) and the brief say the Health page shows notCaughtUp and changesRebased; it does not (see point 6).',\n];\nr.notCovered = [\n  'The counts notCaughtUp and changesRebased themselves (not exposed by any api for an ok run; the database was not read).',\n  'A party\\'s change while NOT named: the cancellation VOID slips at deletion (the station was set back to none before the parties were deleted).',\n  'The phone page during change B and the settlement on the phone (the phone only reads the bill).',\n  'Whether the open till pages in points 5, 8 and 9 ran the f17359759 or the 963605c97 bundle (the tills redeployed mid-run).',\n];\nr.images = pics;\nwriteFileSync(DIR + 'receipt.json', JSON.stringify(r, null, 2) + '\\n');\nconsole.log('points', Object.keys(r.points).length, 'images', pics.length);\n",
 "bundle.mjs": "// Writes docs/qa/proof-2026-11-12/SCRUM-906/proof.mjs: every script of the run as text; `node proof.mjs <folder>` writes\n// them back out. node bundle.mjs\nimport { readFileSync, readdirSync, writeFileSync } from 'node:fs';\nconst HERE = 'C:/Users/waqar/AppData/Local/Temp/claude/9d4c56906b777e8e/317fcfce-2754-44c9-bec5-9a762ab18d03/scratchpad/p906/';\nconst OUT = 'C:/Users/waqar/OneDrive/Desktop/Projects/oto-pos/docs/qa/proof-2026-11-12/SCRUM-906/proof.mjs';\nconst files = {};\nfor (const f of ['driver.mjs', 'go.mjs', 'deploys.mjs', 'pdf_render.py', 'namecheck.mjs', 'scrubfile.mjs', 'finalize.mjs', 'bundle.mjs']) files[f] = readFileSync(HERE + f, 'utf8');\nfor (const f of readdirSync(HERE + 'steps').filter((x) => x.endsWith('.js')).sort()) files['steps/' + f] = readFileSync(HERE + 'steps/' + f, 'utf8');\nconst head = `// SCRUM-906 staging proof harness (the whole BEO kitchen plan reaches the till), as run on 12 November 2026 against\n// oto-app-staging dep-dbqri2rbc2fs73e7s29g, oto-api-staging dep-dbqrjnbbc2fs73e80610, oto-pos-web-staging\n// dep-dbqrm8dckfvc73d9upg0 and oto-pos-staging dep-dbqrm8gn74is73d22drg, all at f17359759 (deploys.json \"before\"); the\n// api and both tills moved to 963605c97 (contains it) at 13:41-13:44 UTC, during point 5 (deploys.json \"after\").\n// One file: every script of the run as text; \\`node proof.mjs <folder>\\` writes them out. The driver keeps ONE headless\n// Chromium open and runs one step file per request (node go.mjs steps/<file>), appending each step and its scrubbed\n// answer to steps.log beside this file. Credentials by NAME only through scripts/agent/env.mjs need(); staff names\n// held in memory for masking only (raw/names.txt in the scratch folder for the name checks, never committed).\n// The run, in order (UTC), as steps.log records it:\n//   deploys.mjs deploys.json before (13:16) | 01-look | 03-health | 04-release | 02-setup (ZZ TEST till Z90601, five\n//   ZZ TEST simulated printers on Virtual box 1) | 05-party1 | 06-parent | 07-tillread | 08-desk | 09-shotfix |\n//   10-beo-side | 11-phone | 12-phone-retake-and-parent-before | 13-staff-change | 14-refresh-wait (failed on a locked\n//   till) | 16-inspect | 17-refresh-again | 15-party2 | 18-slips-print | 19-slips-change | 19b-slips-change-both (first\n//   try stopped on the bar quantity field before any save; fixed and run) | 26-station-back | 20-settle-open (refused\n//   STOCK_SHORT, socks) | 20x-inspect | 20-settle-open again (refusal recorded) | 20b-settle-open-socks0 |\n//   21-phone-open-then-pay | 22-refund | 22b-tax | 23-pdf (pdf_render.py renders it) | 24-bigqty | 25-package-only |\n//   25b-bigqty-packaged | 03-health | 04-release | 27-release-picture | 28-p2-slips-now | 30-cleanup | 31-signout |\n//   POST /quit | deploys.mjs deploys.json after | scrubfile.mjs | finalize.mjs | namecheck.mjs.\n// Picture edits after the run: the band codes on 05f and 05g blacked out (PyMuPDF); 01k removed (a duplicate of 01j);\n// no picture kept of the first staff change on the tills (the step stopped on the locked till); 05c/05d renamed 05d1-05d3.\nimport { mkdirSync, writeFileSync } from 'node:fs';\nimport { dirname, resolve } from 'node:path';\n`;\nconst body = `const FILES = ${JSON.stringify(files, null, 1)};\nconst dir = process.argv[2];\nif (!dir) { console.log(Object.keys(FILES).join('\\\\n')); process.exit(0); }\nfor (const [name, text] of Object.entries(FILES)) { const f = resolve(dir, name); mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, text); }\nconsole.log('written', Object.keys(FILES).length, 'files to', dir);\n`;\nwriteFileSync(OUT, head + body);\nconsole.log('proof.mjs', Object.keys(files).length, 'files');\n",
 "steps/01-look.js": "S.phase = '0: read-only look before anything is made';\nconst r = {};\nconst branch = (await S.call('GET', '/branches')).body.branches.find(b => b.id === S.branchId);\nr.branch = { name: branch.name, partySlipsStationIdAtStart: branch.partySlipsStationId ?? null };\nconst box = (await S.call('GET', `/branches/${S.branchId}/boxes`)).body.boxes.find(b => b.role === 'virtual' && b.slot === 'virtual-1' && b.status === 'online' && !b.archived);\nr.box = box ? { slot: box.slot, status: box.status } : null;\nS.box = box;\n// today's parties at the park on the till (other than ours none should be due for slips)\nconst ev = (await S.call('GET', `/events?branchId=${S.branchId}&type=party`)).body;\nconst parties = (ev?.events ?? []).map(e => ({ id: e.id, zz: S.isZz(e.title), start: e.startTime ?? null, end: e.endTime ?? null }));\nfor (const e of ev?.events ?? []) if (!S.isZz(e.title)) { S.hidden.push(String(e.title).trim()); }\nr.todaysParties = { count: parties.length, notZz: parties.filter(p => !p.zz).length, list: parties.map(p => ({ zz: p.zz, start: p.start, end: p.end })) };\n// the till's menu at the park\nconst menu = (await S.call('GET', `/branches/${S.branchId}/menu`)).body;\nconst live = p => p.active && !p.archivedAt && p.code && (!p.branchId || p.branchId === S.branchId) && p.kind === 'menu';\nconst kitchen = menu.products.filter(p => live(p) && p.effectivePrepStation === 'kitchen');\nconst bar = menu.products.filter(p => live(p) && p.effectivePrepStation === 'bar');\nconst nowhere = menu.products.filter(p => live(p) && !['kitchen', 'bar'].includes(p.effectivePrepStation));\nconst fmt = p => `${p.code} ${p.name} ${p.priceSatang / 100}/${(p.effectiveWeekendSatang ?? p.priceSatang) / 100} ${p.effectivePrepStation ?? '-'}`;\nr.menu = { kitchen: kitchen.length, bar: bar.length, nowhere: nowhere.length,\n  water: menu.products.filter(p => /water/i.test(p.name) && p.active && !p.archivedAt).map(p => `${fmt(p)} kind=${p.kind}`),\n  kitchenSample: kitchen.slice(0, 40).map(fmt), barSample: bar.slice(0, 25).map(fmt), nowhereSample: nowhere.slice(0, 25).map(fmt) };\nS.menu = menu;\nS.receipt.reads.look = r;\nreturn r;\n",
 "steps/02-setup.js": "S.phase = 'setup: ZZ TEST printers on Virtual box 1 and a ZZ TEST till';\nS.assert.ok(S.box, 'Virtual box 1 online');\nconst ADDRESS = { kids_band: '192.0.2.96:9201', adult_band: '192.0.2.96:9202', receipt: '192.0.2.96:9203', kitchen: '192.0.2.96:9204', bar: '192.0.2.96:9205' };\nconst defs = {\n  kids_band: { kind: 'band_printer', label: 'ZZ TEST SCRUM-906 kids band printer', model: '4B-2082A', protocol: 'tspl2' },\n  adult_band: { kind: 'band_printer', label: 'ZZ TEST SCRUM-906 adult band printer', model: '4B-2082A', protocol: 'tspl2' },\n  receipt: { kind: 'receipt_printer', label: 'ZZ TEST SCRUM-906 receipt printer', model: 'Xprinter XP-80', protocol: 'escpos' },\n  kitchen: { kind: 'kitchen_printer', label: 'ZZ TEST SCRUM-906 kitchen printer', model: 'Xprinter XP-80', protocol: 'escpos' },\n  bar: { kind: 'bar_printer', label: 'ZZ TEST SCRUM-906 bar printer', model: 'Xprinter XP-80', protocol: 'escpos' },\n};\nS.devices = S.devices ?? {};\nfor (const [role, d] of Object.entries(defs)) {\n  if (S.devices[role]) continue;\n  const id = S.randomUUID();\n  const r = await S.call('POST', `/boxes/${S.box.id}/devices`, { id, kind: d.kind, label: d.label, transport: 'simulated', model: d.model, protocol: d.protocol, address: ADDRESS[role] });\n  S.assert.equal(r.status, 200, `device ${role} ${JSON.stringify(r.body).slice(0, 200)}`);\n  S.devices[role] = { id: r.body.device.id, label: d.label, kind: d.kind };\n  S.receipt.created.push({ kind: 'device', role, id: r.body.device.id, label: d.label }); S.save();\n}\nconst stations = (await S.call('GET', `/branches/${S.branchId}/stations?includeArchived=true`)).body.stations;\nconst prefix = Array.from({ length: 99 }, (_, i) => `Z906${String(i + 1).padStart(2, '0')}`).find(p => !stations.some(s => s.codePrefix === p));\nS.fixtureName = `ZZ TEST SCRUM-906 proof till ${Date.now()}`;\nconst devices = Object.keys(defs).map(role => ({ role, deviceId: S.devices[role].id }));\nconst made = await S.call('POST', `/branches/${S.branchId}/stations`, { name: S.fixtureName, kind: 'till', boxId: S.box.id, codePrefix: prefix, accessScope: 'all_staff', paymentRouting: { card: 'manual', qr: 'none' }, capabilities: [], devices });\nS.assert.equal(made.status, 200, 'station ' + JSON.stringify(made.body).slice(0, 300));\nS.station = made.body.station;\nS.receipt.created.push({ kind: 'station', id: S.station.id, name: S.fixtureName, prefix }); S.save();\nreturn { station: S.fixtureName, prefix, devices: S.station.devices.map(d => `${d.role}: ${d.label}`) };\n",
 "steps/03-health.js": "S.phase = '6: the job register on the Health api (read only)';\nconst h = await S.call('GET', '/ops/health');\nconst body = h.body ?? {};\nconst keys = Object.keys(body);\nconst find = (o, d = 0) => {\n  if (!o || typeof o !== 'object' || d > 4) return null;\n  if (Array.isArray(o)) { for (const x of o) { const f = find(x, d + 1); if (f) return f; } return null; }\n  if (Object.values(o).some(v => v === 'job:parties.slips')) return o;\n  for (const v of Object.values(o)) { const f = find(v, d + 1); if (f) return f; }\n  return null;\n};\nconst job = find(body);\nconst r = { status: h.status, topKeys: keys, job };\n(S.receipt.reads.health ??= []).push({ at: new Date().toISOString(), ...r });\nreturn r;\n",
 "steps/04-release.js": "S.phase = '6: the release, read back through the api (audit trail, print record), never the database';\nconst from = '2026-11-12T13:05:00.000Z';\nconst audit = async (action) => {\n  const r = await S.call('GET', `/audit?action=${encodeURIComponent(action)}&from=${from}&limit=200&count=true`);\n  return { status: r.status, total: r.body?.total ?? null, entries: (r.body?.entries ?? []).map(e => ({ at: e.createdAt ?? e.at, bangkok: S.bkk(e.createdAt ?? e.at), branchIsFloresta: e.branchId === S.branchId, entityType: e.entityType, after: e.after ?? null })) };\n};\nconst r = {};\nr.scheduleStart = await audit('party.slips_schedule_start');\nr.rebase = await audit('party.slips_rebase');\nr.change = await audit('party.slips_change');\nr.print = await audit('party.slips_print');\n// every kitchen and bar job queued at the park since the platform release went live (13:11:38Z)\nconst jobs = (await S.call('GET', `/branches/${S.branchId}/print-jobs?limit=200`)).body?.jobs ?? [];\nr.parkJobsSinceApi = jobs.filter(j => Date.parse(j.queuedAt) >= Date.parse('2026-11-12T13:11:00Z')).map(j => ({ bangkok: S.bkk(j.queuedAt), kind: j.kind, status: j.status }));\nr.parkKitchenBarJobsSinceApi = r.parkJobsSinceApi.filter(j => /kitchen|bar/.test(j.kind));\nconst branches = (await S.call('GET', '/branches')).body.branches;\nr.otherParks = [];\nfor (const b of branches) {\n  if (b.id === S.branchId) continue;\n  const jb = (await S.call('GET', `/branches/${b.id}/print-jobs?limit=200`));\n  const ks = (jb.body?.jobs ?? []).filter(j => Date.parse(j.queuedAt) >= Date.parse('2026-11-12T13:11:00Z') && /kitchen|bar/.test(j.kind));\n  r.otherParks.push({ park: b.name, status: jb.status, kitchenBarJobsSinceApi: ks.length });\n}\n(S.receipt.reads.release ??= []).push({ at: new Date().toISOString(), ...r });\nreturn r;\n",
 "steps/05-party1.js": "S.phase = '1: party 1 made in the OTO App (Floresta package, set menu, extras, bar, cake)';\nawait S.openApp();\nconst r = {};\nconst prod = code => S.menu.products.find(p => p.code === code && p.active && !p.archivedAt);\nS.prods = { A: prod('CF-14'), B: prod('CF-13'), drink: prod('CF-63-1'), water: prod('CF-65-6') };\nfor (const [k, p] of Object.entries(S.prods)) S.assert.ok(p, 'till product ' + k);\nr.tillProducts = Object.fromEntries(Object.entries(S.prods).map(([k, p]) => [k, `${p.code} ${p.name} ${p.priceSatang / 100} baht weekday, ${p.effectivePrepStation}`]));\nS.P1 = 'ZZ TEST 906 party';\nconst ev = await S.appCall('POST', '/admin/events', { eventType: 'birthday', title: S.P1, branchId: S.APP_FLORESTA, eventDate: S.today, startTime: '19:00', endTime: '22:00', durationMinutes: 180, numChildren: 2, numAdults: 2, childName: 'ZZ TEST child', status: 'upcoming' });\nS.assert.equal(ev.status, 201, 'party created ' + JSON.stringify(ev.body).slice(0, 200));\nS.p1 = ev.body.id;\nS.receipt.created.push({ kind: 'oto-app party', id: S.p1, title: S.P1 }); S.save();\nconst snap = await S.appCall('POST', `/beo/events/${S.p1}/package-snapshot`, { templateId: S.FLORESTA_PACKAGE });\nS.assert.equal(snap.status, 201, 'package applied');\nr.package = { status: snap.status, name: snap.body?.packageName ?? null, slipsTimeAtApply: snap.body?.slipsTime ?? null, setMenuTemplateId: snap.body?.setMenuTemplateId ?? null };\n// the schedule must not print party 1 by itself while the proof presses \"Print party slips now\"\nconst later = await S.appCall('PATCH', `/beo/events/${S.p1}/package-snapshot`, { slipsTime: '23:50' });\nr.slipsTimeMoved = { status: later.status, slipsTime: later.body?.slipsTime ?? null };\nconst tmpls = (await S.appCall('GET', '/beo/set-menu-templates')).body;\nS.tmpl = (Array.isArray(tmpls) ? tmpls : []).find(t => t.id === snap.body?.setMenuTemplateId);\nS.assert.ok(S.tmpl, 'the package set menu template');\nr.setMenu = { name: S.tmpl.name, items: S.tmpl.items.map(i => i.type === 'choice_group' ? `${i.label} [${i.options.join(' / ')}]${i.qty ? ' x' + i.qty : ''} codes ${JSON.stringify(i.optionProductCodes ?? {})}` : `${i.label}${i.qty ? ' x' + i.qty : ''} ${i.productCode ?? ''}`) };\nconst beo = (await S.appCall('GET', `/events/${S.p1}/beo`)).body;\nconst kp0 = beo?.kitchenPlan ?? {};\nr.kitchenAfterPackage = { setMenuEnabled: kp0.setMenuEnabled ?? null, setMenuTemplateId: kp0.setMenuTemplateId ?? null, kids: (kp0.menus?.kids ?? []).length };\nconst line = (id, itemName, quantity, price, productCode, source) => ({ id, itemName, quantity, notes: '', included: source === 'set_menu', price, ...(productCode ? { productCode } : {}), ...(source ? { source } : {}) });\nS.p1Kids = [\n  line('zz906-a', S.prods.A.name, 2, 120, S.prods.A.code),\n  line('zz906-b', S.prods.B.name, 1, 0, S.prods.B.code),\n  line('zz906-c', 'ZZ TEST mango sticky rice', 2, 90, null),\n  line('zz906-d', 'ZZ TEST fruit plate', 1, 0, null),\n];\nS.p1Bar = [\n  line('zz906-bar-drink', S.prods.drink.name, 4, 0, S.prods.drink.code, 'set_menu'),\n  line('zz906-bar-water', S.prods.water.name, 2, 0, S.prods.water.code),\n  line('zz906-bar-typed', 'ZZ TEST lemonade pitcher', 2, 0, null),\n];\nconst put = await S.appCall('PUT', `/events/${S.p1}/beo`, {\n  kitchenPlan: { foodRequired: true, setMenuEnabled: kp0.setMenuEnabled ?? true, setMenuTemplateId: kp0.setMenuTemplateId ?? S.tmpl.id,\n    cakeMode: 'INTERNAL', cakeTime: '20:30', cakeNotes: 'ZZ TEST unicorn',\n    menus: { kids: S.p1Kids, adults: [], adultsDiffer: false, kidsFoodTime: '19:30', adultsFoodTime: '' } },\n  barPlan: { serviceTime: '19:15', items: S.p1Bar },\n});\nr.put = { status: put.status, error: put.status < 300 ? null : put.body };\nconst back = (await S.appCall('GET', `/events/${S.p1}/beo`)).body;\nconst show = l => `${l.source === 'set_menu' ? 'SET' : 'EXTRA'} ${l.itemName} x${l.quantity}${l.price ? ' @' + l.price : ''}${l.productCode ? ' [' + l.productCode + ']' : ''}${l.groupId ? ' group ' + l.groupId : ''}`;\nr.beoReadBack = { kids: (back?.kitchenPlan?.menus?.kids ?? []).map(show), bar: (back?.barPlan?.items ?? []).map(show), barTime: back?.barPlan?.serviceTime ?? null,\n  cake: { mode: back?.kitchenPlan?.cakeMode ?? null, time: back?.kitchenPlan?.cakeTime ?? null, notes: back?.kitchenPlan?.cakeNotes ?? null, qty: back?.kitchenPlan?.cakeQuantity ?? null },\n  setMenuEnabled: back?.kitchenPlan?.setMenuEnabled ?? null };\nS.receipt.reads.p1Made = r;\nreturn r;\n",
 "steps/06-parent.js": "S.phase = \"1: the parent's choices through the link's public routes\";\n// word-bounded scrub (a short name must not cut into a dish's name)\nS.scrub = text => {\n  let t = String(text);\n  for (const n of S.needles()) t = t.replace(new RegExp(`(?<![\\\\p{L}\\\\p{N}])${n.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}(?![\\\\p{L}\\\\p{N}])`, 'gu'), '[name]');\n  return t.replace(/[0-9a-f]{48}/g, '<token>');\n};\nconst link = await S.appCall('POST', '/beo/set-menu-selections', { eventId: S.p1, templateId: S.tmpl.id });\nS.assert.equal(link.status, 201, 'parent link');\nS.token = link.body.token; // memory only\nconst pub = await S.appCall('GET', `/beo/set-menu-selections/public/${S.token}`);\nconst groups = (pub.body?.template?.items ?? []).filter(i => i.type === 'choice_group');\nconst selections = groups.map(g => ({ groupId: g.id, chosenOptions: [g.options[0]] }));\nconst sub = await S.appCall('POST', `/beo/set-menu-selections/public/${S.token}/submit`, { selections });\nconst after = await S.appCall('GET', `/beo/set-menu-selections/public/${S.token}`);\nconst r = {\n  getLink: link.status, publicRead: pub.status, submit: { status: sub.status, error: sub.status === 200 ? null : sub.body },\n  parentChose: groups.map(g => `${g.label}: ${g.options[0]}`),\n  parentPageNow: { isSubmitted: after.body?.isSubmitted ?? null, selections: (after.body?.selections ?? []).map(s => `${groups.find(g => g.id === s.groupId)?.label}: ${(s.chosenOptions ?? []).join(', ')}`) },\n};\nconst back = (await S.appCall('GET', `/events/${S.p1}/beo`)).body;\nr.beoKids = (back?.kitchenPlan?.menus?.kids ?? []).map(l => `${l.source === 'set_menu' ? 'SET' : 'EXTRA'} ${l.itemName} x${l.quantity}${l.price ? ' @' + l.price : ''}${l.productCode ? ' [' + l.productCode + ']' : ''}${l.groupId ? ' (group ' + (S.tmpl.items.find(i => i.id === l.groupId)?.label ?? l.groupId) + ')' : ''}`);\nS.receipt.reads.p1Parent = r;\nreturn r;\n",
 "steps/07-tillread.js": "// arg via S.readKey / S.readId: the party read on the till's api (GET /api/parties/:id?branchId=)\nS.phase = S.phase ?? 'till read';\nS.tillRead = async (id, key) => {\n  const t0 = Date.now();\n  const p = await S.party(id);\n  const kp = p.body?.kitchenPlan ?? null;\n  const fmtLine = m => `${m.origin ?? '-'} | ${m.name}${m.chosenOption ? ': ' + m.chosenOption : ''}${m.qty == null ? '' : ' x' + m.qty} | code ${m.productCode ?? '-'} | onTillMenu ${m.onTillMenu ?? '-'}${m.unitPriceSatang != null ? ' | entered ' + m.unitPriceSatang / 100 : ''}${m.note ? ' | note ' + m.note : ''}${m.audience ? ' | ' + m.audience : ''}`;\n  const rec = {\n    at: new Date().toISOString(), ms: Date.now() - t0, route: 'GET /api/parties/:id?branchId=<Central Floresta>', status: p.status,\n    error: p.status === 200 ? null : p.body?.error ?? null,\n    title: p.body?.event?.title ?? null, planStatus: p.body?.planStatus ?? null,\n    package: p.body?.plan?.package?.name ?? null,\n    kitchenPlan: kp ? {\n      kitchen: kp.kitchen, cake: kp.cake ?? null,\n      lines: kp.setMenu.map(fmtLine),\n      bar: kp.barItems.map(b => `${b.origin ?? '-'} | ${b.name} x${b.qty} | code ${b.productCode ?? '-'} | onTillMenu ${b.onTillMenu ?? '-'}${b.unitPriceSatang != null ? ' | entered ' + b.unitPriceSatang / 100 : ''}${b.note ? ' | note ' + b.note : ''}`),\n    } : null,\n    planSetMenuLines: p.body?.plan ? p.body.plan.setMenu.length : null,\n    slips: p.body?.slips ? { slipsTime: p.body.slips.slipsTime ?? null, station: p.body.slips.station?.name ?? null, records: (p.body.slips.records ?? []).map(x => `${x.station} run ${x.run} ${x.trigger} ${x.status}${x.variant ? ' ' + x.variant : ''}`) } : null,\n    settlement: p.body?.event?.party?.settlement ? { state: p.body.event.party.settlement.state } : null,\n  };\n  if (key) (S.receipt.reads.tillReads ??= {})[key] = rec;\n  return rec;\n};\nreturn await S.tillRead(S.p1, 'p1-after-parent');\n",
 "steps/08-desk.js": "S.phase = \"1: the till's party page, desk size\";\nif (!S.pages.till) await S.signIn('till', 'STAGING_RECEPTION_PHONE', 'STAGING_RECEPTION_PASSWORD', { width: 1680, height: 1050 });\nconst till = S.pages.till.page;\nawait S.unlock('till');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..'), S.otherParties(page)];\nS.cardOf = (page, title) => page.locator('div.font-bold', { hasText: new RegExp(`^${title}$`) }).first().locator('xpath=ancestor::div[contains(@class,\"bg-card\")][1]');\nS.cardText = async (page, title) => S.flat(await S.cardOf(page, title).innerText().catch(() => ''));\nS.openParty = async (page, id, title) => {\n  await page.goto(`/parties?party=${id}`); await page.waitForTimeout(3500);\n  if (!(await page.getByText(title).first().isVisible().catch(() => false))) { await page.goto('/parties'); await page.waitForTimeout(3000); await page.getByText(title).first().click(); await page.waitForTimeout(3000); }\n  await page.locator('div.font-bold', { hasText: /^Kitchen plan$/ }).first().waitFor({ timeout: 30000 });\n};\nawait S.openParty(till, S.p1, S.P1);\nconst r = { url: new URL(till.url()).pathname + new URL(till.url()).search };\nr.kitchen = await S.cardText(till, 'Kitchen plan');\nr.bar = await S.cardText(till, 'Bar plan');\nawait S.cardOf(till, 'Kitchen plan').scrollIntoViewIfNeeded();\nawait S.shot(till, '01a-till-desk-party-page-top.png');\nawait S.shot(till, '01b-till-desk-kitchen-plan-card.png', [], { element: S.cardOf(till, 'Kitchen plan') });\nawait S.shot(till, '01c-till-desk-bar-plan-card.png', [], { element: S.cardOf(till, 'Bar plan') });\nS.receipt.reads.p1Desk = r;\nreturn r;\n",
 "steps/09-shotfix.js": "S.phase = '1: pictures retaken with short names matched case-sensitively (a name like \"[name]\" must not black out \"min\")';\nconst { resolve } = S;\nS.shot = async (page, name, extra = [], opts = {}) => {\n  for (const loc of S.inPlace(page)) await loc.evaluateAll(els => { for (const e of els) e.setAttribute('data-zz-mask', '1'); }).catch(() => {});\n  await page.evaluate((list) => {\n    if (!document.getElementById('zz-mask-style')) { const st = document.createElement('style'); st.id = 'zz-mask-style'; st.textContent = '[data-zz-mask]{background:#18181b!important;color:#18181b!important;border-color:#18181b!important;border-radius:2px} [data-zz-mask] *{color:#18181b!important;background:#18181b!important}'; document.head.appendChild(st); }\n    const esc = s => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n    const res = list.map(s => new RegExp(`(?<![\\\\p{L}\\\\p{N}])${esc(s)}(?![\\\\p{L}\\\\p{N}])`, s.length <= 4 ? 'u' : 'iu'));\n    const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n    while (w.nextNode()) { const v = w.currentNode.nodeValue || ''; if (v.trim() && res.some(r => r.test(v))) w.currentNode.parentElement?.setAttribute('data-zz-mask', '1'); }\n    for (const el of document.querySelectorAll('input,textarea')) { if (res.some(r => r.test(el.value || ''))) el.setAttribute('data-zz-mask', '1'); }\n  }, S.needles());\n  try {\n    if (opts.element) await opts.element.screenshot({ path: resolve(S.out, name), animations: 'disabled', mask: [...S.masks(page), ...extra], maskColor: '#18181b' });\n    else await page.screenshot({ path: resolve(S.out, name), animations: 'disabled', ...opts, mask: [...S.masks(page), ...extra], maskColor: '#18181b' });\n  } finally {\n    await page.evaluate(() => { for (const el of document.querySelectorAll('[data-zz-mask]')) el.removeAttribute('data-zz-mask'); }).catch(() => {});\n  }\n  S.shots.push(name);\n  return name;\n};\nS.scrub = text => {\n  let t = String(text);\n  for (const n of S.needles()) t = t.replace(new RegExp(`(?<![\\\\p{L}\\\\p{N}])${n.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}(?![\\\\p{L}\\\\p{N}])`, n.length <= 4 ? 'gu' : 'giu'), '[name]');\n  return t.replace(/[0-9a-f]{48}/g, '<token>');\n};\nconst till = S.pages.till.page;\nawait till.mouse.wheel(0, -3000); await till.waitForTimeout(500);\nawait S.shot(till, '01a-till-desk-party-page-top.png');\nawait S.shot(till, '01b-till-desk-kitchen-plan-card.png', [], { element: S.cardOf(till, 'Kitchen plan') });\nawait S.shot(till, '01c-till-desk-bar-plan-card.png', [], { element: S.cardOf(till, 'Bar plan') });\nreturn S.shots;\n",
 "steps/10-beo-side.js": "S.phase = '1: the BEO side of party 1 (the OTO App editor), pictures';\nconst page = S.app.page;\nS.openBeo = async (id) => {\n  await page.goto(S.APP + '/studio/events/kanban?beo=' + id, { waitUntil: 'domcontentloaded', timeout: 120000 });\n  await page.getByTestId('accordion-event-info').waitFor({ timeout: 120000 });\n  await page.waitForTimeout(2500);\n};\nS.openSection = async (tid) => {\n  const trig = page.getByTestId(tid).first();\n  await trig.waitFor({ state: 'visible', timeout: 60000 });\n  if ((await trig.getAttribute('data-state')) !== 'open') { await trig.click(); await page.waitForTimeout(900); }\n};\nS.appShot = async (name, tid, block = 'start') => {\n  if (tid) { const l = page.getByTestId(tid).first(); await l.scrollIntoViewIfNeeded(); await l.evaluate((el, b) => el.scrollIntoView({ block: b }), block); await page.waitForTimeout(500); }\n  await S.hideBoard(page);\n  try { return await S.shot(page, name, [], { element: page.locator('[role=dialog]').first() }); } finally { await S.showBoard(page); }\n};\nS.inPlace = p => [];\nawait S.openBeo(S.p1);\nawait S.openSection('accordion-kitchen-plan');\nawait page.getByTestId('button-menu-tab-kids').click().catch(() => {});\nawait page.waitForTimeout(600);\nconst rows = await page.evaluate(() => [...document.querySelectorAll('[data-testid^=\"menu-item-kids-\"]')].filter(r => /^menu-item-kids-\\d+$/.test(r.getAttribute('data-testid'))).map(r => (r.innerText || '').replace(/\\s+/g, ' ').trim()));\nconst setBlock = await page.evaluate(() => { const b = document.querySelector('.border-emerald-500\\\\/40'); return b ? (b.innerText || '').replace(/\\s+/g, ' ').trim().slice(0, 900) : null; });\nawait S.appShot('01d-beo-kitchen-plan-set-menu.png', 'accordion-kitchen-plan', 'start');\nawait S.appShot('01e-beo-kitchen-plan-extra-lines.png', 'menu-item-kids-8', 'center');\nconst cakeText = await page.getByTestId('input-cake-notes').first().inputValue().catch(() => null);\nawait S.appShot('01f-beo-cake.png', 'input-cake-notes', 'center');\nawait S.openSection('accordion-bar-plan');\nconst barRows = await page.evaluate(() => [...document.querySelectorAll('[data-testid^=\"bar-item-\"]')].filter(r => /^bar-item-\\d+$/.test(r.getAttribute('data-testid'))).map(r => (r.innerText || '').replace(/\\s+/g, ' ').trim()));\nawait S.appShot('01g-beo-bar-plan.png', 'accordion-bar-plan', 'start');\nconst r = { kidsRows: rows.map(S.scrub), setBlock: setBlock && S.scrub(setBlock), cakeNotes: cakeText, barRows: barRows.map(S.scrub) };\nS.receipt.reads.p1Beo = r;\nreturn r;\n",
 "steps/11-phone.js": "S.phase = \"1: the till's party page, phone size\";\nif (!S.pages.phone) await S.signIn('phone', 'STAGING_RECEPTION_PHONE', 'STAGING_RECEPTION_PASSWORD', { width: 390, height: 844 });\nconst phone = S.pages.phone.page;\nawait S.unlock('phone');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..'), S.otherParties(page)];\nawait phone.goto(`/parties?party=${S.p1}`); await phone.waitForTimeout(4000);\nlet body = S.flat(await phone.locator('body').innerText());\nif (!/Kitchen plan/i.test(body)) {\n  await phone.goto('/parties'); await phone.waitForTimeout(3000);\n  await phone.getByText(S.P1).first().click(); await phone.waitForTimeout(3500);\n  body = S.flat(await phone.locator('body').innerText());\n}\nconst r = { url: new URL(phone.url()).pathname + new URL(phone.url()).search, hasKitchen: /Kitchen plan/i.test(body) };\nr.kitchenToBar = body.match(/Kitchen plan[^]*?(?=Run of show|Kitchen & bar slips|Timeline|$)/i)?.[0]?.slice(0, 1500) ?? body.slice(0, 1500);\nawait S.shot(phone, '01h-till-phone-party-page-top.png');\nconst k = phone.getByText('Kitchen plan', { exact: false }).first();\nawait k.scrollIntoViewIfNeeded().catch(() => {}); await k.evaluate(el => el.scrollIntoView({ block: 'start' })).catch(() => {}); await phone.waitForTimeout(600);\nawait S.shot(phone, '01i-till-phone-kitchen-plan.png');\nawait phone.mouse.wheel(0, 700); await phone.waitForTimeout(600);\nawait S.shot(phone, '01j-till-phone-kitchen-plan-cake-and-bar.png');\nawait phone.mouse.wheel(0, 700); await phone.waitForTimeout(600);\nawait S.shot(phone, '01k-till-phone-bar-plan.png');\nS.receipt.reads.p1Phone = r;\nreturn r;\n",
 "steps/12-phone-retake-and-parent-before.js": "S.phase = \"1/2: phone pictures retaken (no structural mask on the detail), the parent's link page before the staff change\";\nconst phone = S.pages.phone.page;\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nawait phone.mouse.wheel(0, -4000); await phone.waitForTimeout(500);\nawait S.shot(phone, '01h-till-phone-party-page-top.png');\nconst k = phone.getByText('Kitchen plan', { exact: false }).first();\nawait k.evaluate(el => el.scrollIntoView({ block: 'start' })).catch(() => {}); await phone.waitForTimeout(600);\nawait S.shot(phone, '01i-till-phone-kitchen-plan.png');\nawait phone.mouse.wheel(0, 700); await phone.waitForTimeout(600);\nawait S.shot(phone, '01j-till-phone-kitchen-plan-cake-and-bar.png');\ntry { require('node:fs'); } catch {}\n// the parent's own page (the public link), as the parent sees it, before the staff change\nconst ctx = await S.browser.newContext({ viewport: { width: 420, height: 900 }, timezoneId: 'Asia/Bangkok', locale: 'en-GB', colorScheme: 'light' });\nconst pp = await ctx.newPage(); S.watch(pp, 'parent-link');\nawait pp.goto(`${S.APP}/menu-select/${S.token}`, { waitUntil: 'domcontentloaded', timeout: 120000 });\nawait pp.getByTestId('list-submitted-choices').waitFor({ timeout: 60000 }).catch(() => {});\nawait pp.waitForTimeout(1500);\nconst list = S.flat(await pp.getByTestId('list-submitted-choices').innerText().catch(() => ''));\nawait S.shot(pp, '02a-parent-link-page-before-staff-change.png', [], { fullPage: true });\nS.parentCtx = ctx; S.parentPage = pp;\nS.receipt.reads.parentPageBefore = { list };\nreturn { list };\n",
 "steps/13-staff-change.js": "S.phase = \"2: staff change Fried rice from Veggie to Chicken in the BEO after the parent's answer\";\nconst page = S.app.page;\nS.inPlace = p => [];\nawait S.openSection('accordion-kitchen-plan');\n// the resolved set-menu line of the Fried rice group\nconst idx = await page.evaluate(() => {\n  const rows = [...document.querySelectorAll('[data-testid^=\"menu-item-kids-\"]')].filter(r => /^menu-item-kids-\\d+$/.test(r.getAttribute('data-testid')));\n  const row = rows.find(r => /\\bVeggie\\b/.test(r.innerText) && /\\(Fried rice\\)/.test(r.innerText));\n  return row ? row.getAttribute('data-testid').split('-').pop() : null;\n});\nS.assert.ok(idx !== null, 'the Fried rice line');\nconst tid = `input-menu-name-kids-${idx}`;\nconst l = page.getByTestId(tid).first();\nawait l.scrollIntoViewIfNeeded(); await l.evaluate(el => el.scrollIntoView({ block: 'center' }));\nawait l.click(); await page.waitForTimeout(300);\nconst input = page.locator(`[data-testid=\"${tid}\"] input, input[data-testid=\"${tid}\"]`).first();\nconst field = (await input.count()) ? input : page.locator(':focus');\nawait field.fill('Chicken');\nawait page.keyboard.press('Tab'); await page.waitForTimeout(500);\nconst rowText = S.flat(await page.getByTestId(`menu-item-kids-${idx}`).innerText());\nawait S.appShot('02b-beo-staff-change-fried-rice-chicken-before-save.png', `menu-item-kids-${idx}`, 'center');\nconst done = page.waitForResponse(rr => /\\/api\\/events\\/[^/]+\\/beo$/.test(new URL(rr.url()).pathname) && rr.request().method() === 'PUT', { timeout: 120000 });\nawait page.getByTestId('button-save-beo').click();\nconst resp = await done;\nS.changeAt = Date.now();\nconst toasts = (await page.locator('li[role=status]').allInnerTexts().catch(() => [])).map(t => S.flat(t));\nconst r = { line: rowText, save: { status: resp.status(), at: new Date(S.changeAt).toISOString() }, toasts };\nconst back = (await S.appCall('GET', `/events/${S.p1}/beo`)).body;\nr.beoKids = (back?.kitchenPlan?.menus?.kids ?? []).filter(x => x.source === 'set_menu').map(x => `${x.itemName}${x.groupId ? ' (group ' + (S.tmpl.items.find(i => i.id === x.groupId)?.label ?? '?') + ')' : ''}`);\nconst api = await S.tillRead(S.p1, 'p1-after-staff-change');\nr.apiRightAfter = { ms: Date.now() - S.changeAt, friedRice: api.kitchenPlan?.lines.find(x => /Fried rice/.test(x)) ?? null };\nS.receipt.reads.staffChange = r;\nreturn r;\n",
 "steps/14-refresh-wait.js": "S.phase = \"2: how long the open till pages take to show the staff's choice (no reload, no click)\";\nconst desk = S.pages.till.page, phone = S.pages.phone.page;\nconst has = async (p) => /Fried rice · Chicken/.test(S.flat(await p.locator('body').innerText().catch(() => '')));\nconst r = { savedAt: new Date(S.changeAt).toISOString(), desk: null, phone: null };\nconst deadline = S.changeAt + 160000;\nwhile (Date.now() < deadline && (r.desk === null || r.phone === null)) {\n  if (r.desk === null && await has(desk)) r.desk = { seconds: Math.round((Date.now() - S.changeAt) / 1000), at: new Date().toISOString() };\n  if (r.phone === null && await has(phone)) r.phone = { seconds: Math.round((Date.now() - S.changeAt) / 1000), at: new Date().toISOString() };\n  await S.sleep(2000);\n}\nr.deskStillVeggie = /Fried rice · Veggie/.test(S.flat(await desk.locator('body').innerText()));\n// the focus path: bring the desk page to the front and see that it reads at once (only when it had not yet)\nif (r.desk === null) {\n  const t0 = Date.now();\n  await desk.bringToFront(); await desk.evaluate(() => { window.dispatchEvent(new Event('focus')); document.dispatchEvent(new Event('visibilitychange')); });\n  for (let i = 0; i < 20 && !(await has(desk)); i++) await S.sleep(500);\n  r.deskOnFocus = { seconds: Math.round((Date.now() - t0) / 1000), shows: await has(desk) };\n}\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nawait S.cardOf(desk, 'Kitchen plan').scrollIntoViewIfNeeded().catch(() => {});\nawait S.shot(desk, '02c-till-desk-staff-choice-fried-rice-chicken.png', [], { element: S.cardOf(desk, 'Kitchen plan') });\nconst k = phone.getByText('Kitchen plan', { exact: false }).first();\nawait k.evaluate(el => el.scrollIntoView({ block: 'start' })).catch(() => {}); await phone.waitForTimeout(500);\nawait S.shot(phone, '02d-till-phone-staff-choice-fried-rice-chicken.png');\n// the parent's own page, reloaded\nawait S.parentPage.reload({ waitUntil: 'domcontentloaded' }); await S.parentPage.getByTestId('list-submitted-choices').waitFor({ timeout: 60000 }).catch(() => {}); await S.parentPage.waitForTimeout(1200);\nr.parentList = S.flat(await S.parentPage.getByTestId('list-submitted-choices').innerText().catch(() => ''));\nawait S.shot(S.parentPage, '02e-parent-link-page-after-staff-change.png', [], { fullPage: true });\nconst pub = await S.appCall('GET', `/beo/set-menu-selections/public/${S.token}`);\nr.parentApi = (pub.body?.selections ?? []).map(s => `${S.tmpl.items.find(i => i.id === s.groupId)?.label}: ${(s.chosenOptions ?? []).join(', ')}`);\nS.receipt.reads.refresh = r;\nreturn r;\n",
 "steps/15-party2.js": "S.phase = '3: party 2, a kitchen and bar plan and NO package';\nS.P2 = 'ZZ TEST 906 no package';\nconst ev = await S.appCall('POST', '/admin/events', { eventType: 'birthday', title: S.P2, branchId: S.APP_FLORESTA, eventDate: S.today, startTime: '16:00', endTime: '18:00', durationMinutes: 120, numChildren: 3, numAdults: 1, childName: 'ZZ TEST child two', status: 'upcoming' });\nS.assert.equal(ev.status, 201, 'party 2 created ' + JSON.stringify(ev.body).slice(0, 200));\nS.p2 = ev.body.id;\nS.receipt.created.push({ kind: 'oto-app party', id: S.p2, title: S.P2 }); S.save();\nconst line = (id, itemName, quantity, price, productCode, source) => ({ id, itemName, quantity, notes: '', included: source === 'set_menu', price, ...(productCode ? { productCode } : {}), ...(source ? { source } : {}) });\nS.p2Kids = [line('zz906-p2-a', 'ZZ TEST nuggets plate', 3, 0, null), line('zz906-p2-b', 'French fries', 1, 0, 'CF-11')];\nconst put = await S.appCall('PUT', `/events/${S.p2}/beo`, {\n  kitchenPlan: { foodRequired: true, setMenuEnabled: false, setMenuTemplateId: null, cakeMode: 'EXTERNAL', cakeTime: '17:00', cakeNotes: 'ZZ TEST family cake',\n    menus: { kids: S.p2Kids, adults: [], adultsDiffer: false, kidsFoodTime: '16:30', adultsFoodTime: '' } },\n  barPlan: { serviceTime: '16:15', items: [line('zz906-p2-water', 'Mineral water', 2, 0, 'CF-65-6')] },\n});\nconst r = { put: put.status };\nr.till = await S.tillRead(S.p2, 'p2');\n// settling it, as the till's Settle form asks (the till offers no Settle button for a party with no package)\nconst pv = await S.call('POST', `/parties/${S.p2}/settle/preview`, { branchId: S.branchId, stationId: S.station.id, kids: 3, adults: 1, socksGiven: 0, addOnIds: [], entertainmentIds: [] });\nr.settlePreview = { route: 'POST /api/parties/:id/settle/preview', status: pv.status, code: pv.body?.error?.code ?? null, words: pv.body?.error?.message ?? null };\nconst desk = S.pages.till.page;\nawait S.unlock('till');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nawait S.openParty(desk, S.p2, S.P2);\nconst buttons = [];\nfor (const b of await desk.getByRole('button').all()) { const t = S.flat(await b.innerText().catch(() => '')); if (/Settle party|Add tickets|Edit party|Fully paid|Print party slips now|Add F&B/.test(t) && await b.isVisible()) buttons.push(t); }\nr.deskButtons = buttons;\nr.deskKitchen = await S.cardText(desk, 'Kitchen plan');\nr.deskBar = await S.cardText(desk, 'Bar plan');\nawait desk.mouse.wheel(0, -3000); await desk.waitForTimeout(400);\nawait S.shot(desk, '03a-till-desk-no-package-party.png');\nawait S.shot(desk, '03b-till-desk-no-package-kitchen-plan.png', [], { element: S.cardOf(desk, 'Kitchen plan') });\nS.receipt.reads.p2 = r;\nreturn r;\n",
 "steps/16-inspect.js": "S.phase = '2: what the open till pages show now';\nconst out = {};\nfor (const label of ['till', 'phone']) {\n  const p = S.pages[label].page;\n  const body = S.flat(await p.locator('body').innerText().catch(() => ''));\n  out[label] = { url: new URL(p.url()).pathname + new URL(p.url()).search, locked: await p.getByRole('heading', { name: 'Locked', exact: true }).isVisible().catch(() => false), chicken: /Fried rice · Chicken/.test(body), veggie: /Fried rice · Veggie/.test(body), text: body.slice(0, 300) };\n}\nout.secondsSinceSave = Math.round((Date.now() - S.changeAt) / 1000);\nreturn out;\n",
 "steps/17-refresh-again.js": "S.phase = \"2: the till pages kept awake (a Shift key every 25 s, no click, no focus), a second staff change Chicken -> Shrimp, timed\";\nconst desk = S.pages.till.page, phone = S.pages.phone.page;\nconst r = {};\nawait S.unlock('till'); await S.unlock('phone');\nawait S.sleep(3000);\nconst txt = async p => S.flat(await p.locator('body').innerText().catch(() => ''));\nr.afterUnlock = { desk: (await txt(desk)).match(/Fried rice · \\w+/)?.[0] ?? null, phone: (await txt(phone)).match(/Fried rice · \\w+/)?.[0] ?? null, phoneUrl: new URL(phone.url()).pathname };\nif (!/Kitchen plan/.test(await txt(phone))) { await phone.goto(`/parties?party=${S.p1}`); await phone.waitForTimeout(4000); if (!/Kitchen plan/.test(await txt(phone))) { await phone.goto('/parties'); await phone.waitForTimeout(3000); await phone.getByText(S.P1).first().click(); await phone.waitForTimeout(3500); } }\nif (!/Kitchen plan/.test(await txt(desk))) await S.openParty(desk, S.p1, S.P1);\nr.beforeChange = { desk: (await txt(desk)).match(/Fried rice · \\w+/)?.[0] ?? null, phone: (await txt(phone)).match(/Fried rice · \\w+/)?.[0] ?? null };\n// the second staff change in the BEO editor\nconst page = S.app.page;\nawait S.openBeo(S.p1);\nawait S.openSection('accordion-kitchen-plan');\nconst idx = await page.evaluate(() => {\n  const rows = [...document.querySelectorAll('[data-testid^=\"menu-item-kids-\"]')].filter(x => /^menu-item-kids-\\d+$/.test(x.getAttribute('data-testid')));\n  const row = rows.find(x => /\\(Fried rice\\)/.test(x.innerText));\n  return row ? row.getAttribute('data-testid').split('-').pop() : null;\n});\nconst tid = `input-menu-name-kids-${idx}`;\nconst l = page.getByTestId(tid).first();\nawait l.scrollIntoViewIfNeeded(); await l.click(); await page.waitForTimeout(300);\nconst input = page.locator(`[data-testid=\"${tid}\"] input, input[data-testid=\"${tid}\"]`).first();\nawait ((await input.count()) ? input : page.locator(':focus')).fill('Shrimp');\nawait page.keyboard.press('Tab'); await page.waitForTimeout(400);\n// keep the tills awake right before the save\nawait desk.keyboard.press('Shift'); await phone.keyboard.press('Shift');\nconst done = page.waitForResponse(rr => /\\/api\\/events\\/[^/]+\\/beo$/.test(new URL(rr.url()).pathname) && rr.request().method() === 'PUT', { timeout: 120000 });\nawait page.getByTestId('button-save-beo').click();\nconst resp = await done;\nconst t0 = Date.now();\nr.save = { status: resp.status(), at: new Date(t0).toISOString() };\nr.desk = null; r.phone = null;\nlet lastPoke = Date.now();\nwhile (Date.now() - t0 < 150000 && (r.desk === null || r.phone === null)) {\n  if (Date.now() - lastPoke > 25000) { await desk.keyboard.press('Shift'); await phone.keyboard.press('Shift'); lastPoke = Date.now(); }\n  if (r.desk === null && /Fried rice · Shrimp/.test(await txt(desk))) r.desk = { seconds: Math.round((Date.now() - t0) / 1000) };\n  if (r.phone === null && /Fried rice · Shrimp/.test(await txt(phone))) r.phone = { seconds: Math.round((Date.now() - t0) / 1000) };\n  await S.sleep(2000);\n}\nr.lockedAtEnd = { desk: await desk.getByRole('heading', { name: 'Locked', exact: true }).isVisible().catch(() => false), phone: await phone.getByRole('heading', { name: 'Locked', exact: true }).isVisible().catch(() => false) };\nS.inPlace = p => [p.getByLabel('Lock screen').locator('..')];\nawait S.cardOf(desk, 'Kitchen plan').scrollIntoViewIfNeeded().catch(() => {});\nawait S.shot(desk, '02c-till-desk-staff-choice-fried-rice-shrimp.png', [], { element: S.cardOf(desk, 'Kitchen plan') });\nconst k = phone.getByText('Kitchen plan', { exact: false }).first();\nawait k.evaluate(el => el.scrollIntoView({ block: 'start' })).catch(() => {}); await phone.waitForTimeout(500);\nawait S.shot(phone, '02d-till-phone-staff-choice-fried-rice-shrimp.png');\nawait S.parentPage.reload({ waitUntil: 'domcontentloaded' }); await S.parentPage.getByTestId('list-submitted-choices').waitFor({ timeout: 60000 }).catch(() => {}); await S.parentPage.waitForTimeout(1200);\nr.parentList = S.flat(await S.parentPage.getByTestId('list-submitted-choices').innerText().catch(() => ''));\nawait S.shot(S.parentPage, '02e-parent-link-page-after-staff-change.png', [], { fullPage: true });\nconst pub = await S.appCall('GET', `/beo/set-menu-selections/public/${S.token}`);\nr.parentApi = (pub.body?.selections ?? []).map(s => `${S.tmpl.items.find(i => i.id === s.groupId)?.label}: ${(s.chosenOptions ?? []).join(', ')}`);\nr.api = (await S.tillRead(S.p1, 'p1-after-second-staff-change')).kitchenPlan?.lines.find(x => /Fried rice/.test(x)) ?? null;\nS.receipt.reads.refresh = r;\nreturn r;\n",
 "steps/18-slips-print.js": "S.phase = '4: the ZZ TEST till named for party slips; one tick; Print party slips now for party 1';\nconst r = {};\nconst b0 = (await S.call('GET', '/branches')).body.branches.find(b => b.id === S.branchId);\nS.assert.equal(b0.partySlipsStationId ?? null, null, 'the park names no party slips station (nobody else is using it)');\nS.seen = { kitchen: (await S.printouts('kitchen')).map(S.keyOf), bar: (await S.printouts('bar')).map(S.keyOf) };\nS.slipsFrom = new Date().toISOString();\nconst named = await S.call('PATCH', `/branches/${S.branchId}`, { partySlipsStationId: S.station.id });\nS.assert.equal(named.status, 200, 'named');\nS.stationNamed = true;\nr.named = { at: S.slipsFrom, status: named.status };\n// one full tick of the job with our till named: nothing should print (party 1's slip time is 23:50; party 2 was not caught up)\nawait S.sleep(75000);\nr.afterOneTick = { jobsAtTill: await S.jobsAtTill(S.slipsFrom), printouts: { kitchen: (await S.printouts('kitchen')).filter(p => !S.seen.kitchen.includes(S.keyOf(p))).length, bar: (await S.printouts('bar')).filter(p => !S.seen.bar.includes(S.keyOf(p))).length } };\n// the press on the desk till\nconst desk = S.pages.till.page;\nawait S.unlock('till');\nawait S.openParty(desk, S.p1, S.P1);\nconst btn = desk.getByRole('button', { name: 'Print party slips now', exact: true });\nawait btn.scrollIntoViewIfNeeded();\nconst resp = desk.waitForResponse(rr => /\\/api\\/parties\\/[^/]+\\/slips\\/print$/.test(new URL(rr.url()).pathname) && rr.request().method() === 'POST', { timeout: 60000 });\nconst pressedAt = new Date().toISOString();\nawait btn.click();\nconst rr = await resp;\nconst rb = await rr.json().catch(() => null);\nr.press = { at: pressedAt, status: rr.status(), run: rb?.run ?? null, slips: (rb?.slips?.records ?? rb?.slips ?? []).length !== undefined ? (rb?.slips?.records ?? []).map(x => `${x.station} run ${x.run} ${x.trigger} ${x.status}`) : null };\n// the printouts as the simulated printers drew them\nconst deadline = Date.now() + 90000;\nlet k = [], b = [];\nwhile (Date.now() < deadline) {\n  k = (await S.printouts('kitchen')).filter(p => !S.seen.kitchen.includes(S.keyOf(p)));\n  b = (await S.printouts('bar')).filter(p => !S.seen.bar.includes(S.keyOf(p)));\n  if (k.length >= 1 && b.length >= 1) break;\n  await S.sleep(3000);\n}\nawait S.sleep(6000);\nk = (await S.printouts('kitchen')).filter(p => !S.seen.kitchen.includes(S.keyOf(p)));\nb = (await S.printouts('bar')).filter(p => !S.seen.bar.includes(S.keyOf(p)));\nr.printouts = { kitchen: k.map(p => ({ seq: p.seq, at: p.at, heightDots: p.heightDots })), bar: b.map(p => ({ seq: p.seq, at: p.at, heightDots: p.heightDots })) };\nif (k[0]) await S.keepPreview('kitchen', k[0], 'p4-print-kitchen.png', S.resolve(S.scratch, 'raw'));\nif (b[0]) await S.keepPreview('bar', b[0], 'p4-print-bar.png', S.resolve(S.scratch, 'raw'));\nfor (const p of k) S.seen.kitchen.push(S.keyOf(p));\nfor (const p of b) S.seen.bar.push(S.keyOf(p));\nr.jobsAtTill = await S.jobsAtTill(S.slipsFrom);\nawait S.sleep(1500);\nconst block = desk.locator('div.font-bold', { hasText: /^Kitchen & bar slips$/ }).first();\nawait block.scrollIntoViewIfNeeded().catch(() => {});\nr.slipsCard = await S.cardText(desk, 'Kitchen & bar slips');\nawait S.shot(desk, '04a-till-desk-slips-card-after-print-now.png', [], { element: S.cardOf(desk, 'Kitchen & bar slips') });\nS.receipt.reads.p4print = r;\nreturn r;\n",
 "steps/19-slips-change.js": "S.phase = '4: one BEO line changed (ZZ TEST fruit plate 1 -> 2) in the editor; VOID and UPDATED once at the kitchen, nothing at the bar';\nconst fs = { copy: (a, b) => S.writeFileSync(b, S.readFileSync(a)) };\nfs.copy(S.resolve(S.scratch, 'raw', 'p4-print-kitchen.png'), S.resolve(S.out, '04b-kitchen-slip-print-now.png'));\nfs.copy(S.resolve(S.scratch, 'raw', 'p4-print-bar.png'), S.resolve(S.out, '04c-bar-slip-print-now.png'));\nconst page = S.app.page;\nawait S.openBeo(S.p1);\nawait S.openSection('accordion-kitchen-plan');\nconst idx = await page.evaluate(() => {\n  const rows = [...document.querySelectorAll('[data-testid^=\"menu-item-kids-\"]')].filter(x => /^menu-item-kids-\\d+$/.test(x.getAttribute('data-testid')));\n  const row = rows.find(x => /ZZ TEST fruit plate/.test(x.innerText));\n  return row ? row.getAttribute('data-testid').split('-').pop() : null;\n});\nS.assert.ok(idx !== null, 'the fruit plate line');\nawait page.getByTestId(`button-qty-plus-kids-${idx}`).click(); await page.waitForTimeout(400);\nconst row = S.flat(await page.getByTestId(`menu-item-kids-${idx}`).innerText());\nconst done = page.waitForResponse(rr => /\\/api\\/events\\/[^/]+\\/beo$/.test(new URL(rr.url()).pathname) && rr.request().method() === 'PUT', { timeout: 120000 });\nawait page.getByTestId('button-save-beo').click();\nconst resp = await done;\nconst t0 = Date.now();\nconst r = { row, save: { status: resp.status(), at: new Date(t0).toISOString() } };\nconst deadline = Date.now() + 150000;\nlet k = [], b = [];\nwhile (Date.now() < deadline) {\n  k = (await S.printouts('kitchen')).filter(p => !S.seen.kitchen.includes(S.keyOf(p)));\n  b = (await S.printouts('bar')).filter(p => !S.seen.bar.includes(S.keyOf(p)));\n  if (k.length >= 2) break;\n  await S.sleep(4000);\n}\nr.firstSeenSeconds = Math.round((Date.now() - t0) / 1000);\nr.change = { kitchen: k.map(p => ({ seq: p.seq, at: p.at })), bar: b.map(p => ({ seq: p.seq, at: p.at })) };\nfor (const [i, p] of k.entries()) await S.keepPreview('kitchen', p, `p4-change-kitchen-${i + 1}.png`, S.resolve(S.scratch, 'raw'));\nfor (const [i, p] of b.entries()) await S.keepPreview('bar', p, `p4-change-bar-${i + 1}.png`, S.resolve(S.scratch, 'raw'));\nfor (const p of k) S.seen.kitchen.push(S.keyOf(p));\nfor (const p of b) S.seen.bar.push(S.keyOf(p));\n// two more ticks: nothing printed twice\nawait S.sleep(130000);\nr.laterLooks = { kitchen: (await S.printouts('kitchen')).filter(p => !S.seen.kitchen.includes(S.keyOf(p))).length, bar: (await S.printouts('bar')).filter(p => !S.seen.bar.includes(S.keyOf(p))).length };\nr.jobsAtTill = await S.jobsAtTill(S.slipsFrom);\nr.audit = (await S.auditOf('party.slips_change', S.p1.toLowerCase())).map(e => ({ bangkok: S.bkk(e.createdAt), run: e.after?.run, cancelled: e.after?.cancelled, slips: (e.after?.slips ?? []).map(s => `${s.station} ${s.variant} ${s.status}`) }));\nr.printAudit = (await S.auditOf('party.slips_print', S.p1.toLowerCase())).map(e => ({ bangkok: S.bkk(e.createdAt), run: e.after?.run, trigger: e.after?.trigger, ourTill: e.after?.stationId === S.station.id, slips: (e.after?.slips ?? []).map(s => `${s.station} ${s.status}`) }));\nS.receipt.reads.p4change = r;\nreturn r;\n",
 "steps/19b-slips-change-both.js": "S.phase = '4: a change that takes something away at both stations (Fried rice Shrimp -> Chicken; ZZ TEST lemonade pitcher 2 -> 1), one save in the editor';\nconst fs = { copy: (a, b) => S.writeFileSync(b, S.readFileSync(a)) };\nfs.copy(S.resolve(S.scratch, 'raw', 'p4-change-kitchen-1.png'), S.resolve(S.out, '04d-kitchen-updated-slip-fruit-plate-up.png'));\nconst page = S.app.page;\nawait S.openBeo(S.p1);\nawait S.openSection('accordion-kitchen-plan');\nconst idx = await page.evaluate(() => {\n  const rows = [...document.querySelectorAll('[data-testid^=\"menu-item-kids-\"]')].filter(x => /^menu-item-kids-\\d+$/.test(x.getAttribute('data-testid')));\n  const row = rows.find(x => /\\(Fried rice\\)/.test(x.innerText));\n  return row ? row.getAttribute('data-testid').split('-').pop() : null;\n});\nconst tid = `input-menu-name-kids-${idx}`;\nawait page.getByTestId(tid).first().scrollIntoViewIfNeeded(); await page.getByTestId(tid).first().click(); await page.waitForTimeout(300);\nconst input = page.locator(`[data-testid=\"${tid}\"] input, input[data-testid=\"${tid}\"]`).first();\nawait ((await input.count()) ? input : page.locator(':focus')).fill('Chicken');\nawait page.keyboard.press('Tab'); await page.waitForTimeout(400);\nawait S.openSection('accordion-bar-plan');\nconst bidx = await page.evaluate(() => {\n  const rows = [...document.querySelectorAll('[data-testid^=\"bar-item-\"]')].filter(x => /^bar-item-\\d+$/.test(x.getAttribute('data-testid')));\n  const row = rows.find(x => /ZZ TEST lemonade pitcher/.test(x.innerText));\n  return row ? row.getAttribute('data-testid').split('-').pop() : null;\n});\nconst q = page.getByTestId(`bar-item-qty-${bidx}`).first();\nawait q.scrollIntoViewIfNeeded();\nawait q.click(); await page.waitForTimeout(300);\nconst qin = page.locator('[data-testid=\"bar-item-qty-' + bidx + '\"] input, input[data-testid=\"bar-item-qty-' + bidx + '\"]').first();\nconst qinput = (await qin.count()) ? qin : page.locator(':focus');\nawait qinput.fill('1'); await page.keyboard.press('Tab'); await page.waitForTimeout(400);\nconst r = { kitchenRow: S.flat(await page.getByTestId(`menu-item-kids-${idx}`).innerText()), barRow: S.flat(await page.getByTestId(`bar-item-${bidx}`).innerText()), barQty: await qinput.inputValue().catch(() => null) };\nawait S.appShot('04e-beo-change-both-stations-before-save.png', `bar-item-${bidx}`, 'center');\nconst seenBefore = { kitchen: [...S.seen.kitchen], bar: [...S.seen.bar] };\nconst done = page.waitForResponse(rr => /\\/api\\/events\\/[^/]+\\/beo$/.test(new URL(rr.url()).pathname) && rr.request().method() === 'PUT', { timeout: 120000 });\nawait page.getByTestId('button-save-beo').click();\nconst resp = await done;\nconst t0 = Date.now();\nr.save = { status: resp.status(), at: new Date(t0).toISOString() };\nconst back = (await S.appCall('GET', `/events/${S.p1}/beo`)).body;\nr.beoBar = (back?.barPlan?.items ?? []).map(x => `${x.itemName} x${x.quantity}`);\nconst deadline = Date.now() + 150000;\nlet k = [], b = [];\nwhile (Date.now() < deadline) {\n  k = (await S.printouts('kitchen')).filter(p => !seenBefore.kitchen.includes(S.keyOf(p)));\n  b = (await S.printouts('bar')).filter(p => !seenBefore.bar.includes(S.keyOf(p)));\n  if (k.length >= 2 && b.length >= 2) break;\n  await S.sleep(4000);\n}\nawait S.sleep(6000);\nk = (await S.printouts('kitchen')).filter(p => !seenBefore.kitchen.includes(S.keyOf(p)));\nb = (await S.printouts('bar')).filter(p => !seenBefore.bar.includes(S.keyOf(p)));\nr.secondsToPrint = Math.round((Date.now() - t0) / 1000);\nr.change = { kitchen: k.map(p => ({ seq: p.seq, at: p.at })), bar: b.map(p => ({ seq: p.seq, at: p.at })) };\nfor (const [i, p] of k.entries()) await S.keepPreview('kitchen', p, `p4b-change-kitchen-${i + 1}.png`, S.resolve(S.scratch, 'raw'));\nfor (const [i, p] of b.entries()) await S.keepPreview('bar', p, `p4b-change-bar-${i + 1}.png`, S.resolve(S.scratch, 'raw'));\nfor (const p of k) S.seen.kitchen.push(S.keyOf(p));\nfor (const p of b) S.seen.bar.push(S.keyOf(p));\nawait S.sleep(130000);\nr.laterLooks = { kitchen: (await S.printouts('kitchen')).filter(p => !S.seen.kitchen.includes(S.keyOf(p))).length, bar: (await S.printouts('bar')).filter(p => !S.seen.bar.includes(S.keyOf(p))).length };\nr.jobsAtTill = (await S.jobsAtTill(S.slipsFrom)).map(j => `${j.bangkok} ${j.role} ${j.status}`);\nr.audit = (await S.auditOf('party.slips_change', S.p1.toLowerCase())).map(e => ({ bangkok: S.bkk(e.createdAt), run: e.after?.run, cancelled: e.after?.cancelled, slips: (e.after?.slips ?? []).map(s => `${s.station} ${s.variant} ${s.status}`) }));\nS.receipt.reads.p4changeBoth = r;\nreturn r;\n",
 "steps/20-settle-open.js": "S.phase = \"5/9: Settle party 1 on the ZZ TEST till: the form's preview, Confirm, Back with nothing taken (the settlement open)\";\nconst till = S.pages.till.page;\nawait S.unlock('till');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nawait S.openParty(till, S.p1, S.P1);\nconst r = {};\nconst previews = [];\nconst onResp = async (resp) => { try { if (/\\/api\\/parties\\/[^/]+\\/settle\\/preview$/.test(new URL(resp.url()).pathname)) previews.push(await resp.json()); } catch { /* ignore */ } };\ntill.on('response', onResp);\nawait till.getByRole('button', { name: 'Settle party', exact: true }).click();\nawait till.getByText('Balance', { exact: true }).first().waitFor({ timeout: 30000 }).catch(() => {});\nawait till.waitForTimeout(2500);\nconst q = previews.at(-1)?.quote ?? null;\nr.preview = q ? { packageName: q.packageName, rateMode: q.rateMode, lines: q.lines.map(l => `${l.role} | ${l.label} | ${l.quantity} x ${l.unitSatang / 100} = ${l.totalSatang / 100}`), packageSatang: q.packageSatang / 100, socks: q.socksSatang / 100, addOns: q.addOnsSatang / 100, total: q.totalSatang / 100, deposit: q.depositSatang / 100, balance: q.balanceSatang / 100 } : null;\nconst dialog = till.getByRole('dialog').last();\nr.formText = S.flat(await dialog.innerText().catch(() => '')).slice(0, 900);\nawait S.shot(till, '05a-settle-party-form-preview.png');\nconst settled = till.waitForResponse(rr => /\\/api\\/parties\\/[^/]+\\/settle$/.test(new URL(rr.url()).pathname) && rr.request().method() === 'POST', { timeout: 60000 });\nawait till.getByRole('button', { name: /^Confirm/ }).click();\nconst sr = await settled;\nconst sb = await sr.json().catch(() => null);\nS.settleSale = sb?.sale?.id ?? null;\nif (S.settleSale) { S.receipt.created.push({ kind: 'party-settlement-sale', id: S.settleSale }); S.save(); }\nif (sr.status() >= 400) { await till.waitForTimeout(1500); r.settleRefused = { status: sr.status(), code: sb?.error?.code ?? null, message: sb?.error?.message ?? null, details: sb?.error?.details ?? null, dialog: S.flat(await till.getByRole('dialog').last().innerText().catch(() => '')).slice(0, 1200) }; await S.shot(till, '05x-settle-refused.png'); S.receipt.reads.p5open = r; return r; }\nr.settle = { status: sr.status(), state: sb?.settlement?.state ?? null, gross: (sb?.sale?.grossSatang ?? 0) / 100, outstanding: (sb?.sale?.outstandingSatang ?? 0) / 100, quoteLines: (sb?.quote?.lines ?? []).map(l => `${l.role} | ${l.label} | ${l.quantity} x ${l.unitSatang / 100} = ${l.totalSatang / 100}`) };\ntill.off('response', onResp);\nawait till.getByTestId('payment-step').waitFor({ timeout: 30000 }); await till.waitForTimeout(2500);\nawait S.shot(till, '05b-settle-payment-step.png');\nconst back = till.getByTestId('payment-step').getByRole('button', { name: 'Back', exact: true });\nawait back.click(); await till.waitForTimeout(3000);\nconst body = S.flat(await till.locator('body').innerText());\nr.afterBack = { bill: body.match(/Party bill[^]*?Outstanding[^฿]*฿[0-9,]+/)?.[0]?.slice(0, 600) ?? null };\nconst buttons = [];\nfor (const b of await till.getByRole('button').all()) { const l = S.flat(await b.innerText().catch(() => '')); if (/Take balance|Fully paid|Resume settlement|Cancel settlement|Settle party/.test(l) && await b.isVisible()) buttons.push({ l, enabled: await b.isEnabled() }); }\nr.afterBack.buttons = buttons;\nawait till.mouse.wheel(0, -3000); await till.waitForTimeout(400);\nawait S.shot(till, '09a-till-desk-settlement-open-party-bill.png');\nS.receipt.reads.p5open = r;\nreturn r;\n",
 "steps/20b-settle-open-socks0.js": "S.phase = \"5/9 (again, socks 0: staging has none in stock): Settle party 1 on the ZZ TEST till: the form's preview, Confirm, Back with nothing taken (the settlement open)\";\nconst till = S.pages.till.page;\nawait S.unlock('till');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nawait S.openParty(till, S.p1, S.P1);\nconst r = {};\nconst previews = [];\nconst onResp = async (resp) => { try { if (/\\/api\\/parties\\/[^/]+\\/settle\\/preview$/.test(new URL(resp.url()).pathname)) previews.push(await resp.json()); } catch { /* ignore */ } };\ntill.on('response', onResp);\nawait till.getByRole('button', { name: 'Settle party', exact: true }).click();\nawait till.getByText('Balance', { exact: true }).first().waitFor({ timeout: 30000 }).catch(() => {});\nawait till.waitForTimeout(2500);\nconst socks = till.getByText('Socks given', { exact: true }).locator('xpath=ancestor::div[.//button][1]');\nfor (let i = 0; i < 2; i++) { await socks.getByRole('button').first().click(); await till.waitForTimeout(900); }\nawait till.waitForTimeout(2000);\nconst q = previews.at(-1)?.quote ?? null;\nr.preview = q ? { packageName: q.packageName, rateMode: q.rateMode, lines: q.lines.map(l => `${l.role} | ${l.label} | ${l.quantity} x ${l.unitSatang / 100} = ${l.totalSatang / 100}`), packageSatang: q.packageSatang / 100, socks: q.socksSatang / 100, addOns: q.addOnsSatang / 100, total: q.totalSatang / 100, deposit: q.depositSatang / 100, balance: q.balanceSatang / 100 } : null;\nconst dialog = till.getByRole('dialog').last();\nr.formText = S.flat(await dialog.innerText().catch(() => '')).slice(0, 900);\nawait S.shot(till, '05c-settle-party-form-socks-0.png');\nconst settled = till.waitForResponse(rr => /\\/api\\/parties\\/[^/]+\\/settle$/.test(new URL(rr.url()).pathname) && rr.request().method() === 'POST', { timeout: 60000 });\nawait till.getByRole('button', { name: /^Confirm/ }).click();\nconst sr = await settled;\nconst sb = await sr.json().catch(() => null);\nS.settleSale = sb?.sale?.id ?? null;\nif (S.settleSale) { S.receipt.created.push({ kind: 'party-settlement-sale', id: S.settleSale }); S.save(); }\nif (sr.status() >= 400) { await till.waitForTimeout(1500); r.settleRefused = { status: sr.status(), code: sb?.error?.code ?? null, message: sb?.error?.message ?? null, details: sb?.error?.details ?? null, dialog: S.flat(await till.getByRole('dialog').last().innerText().catch(() => '')).slice(0, 1200) }; await S.shot(till, '05x-settle-refused-again.png'); S.receipt.reads.p5open = r; return r; }\nr.settle = { status: sr.status(), state: sb?.settlement?.state ?? null, gross: (sb?.sale?.grossSatang ?? 0) / 100, outstanding: (sb?.sale?.outstandingSatang ?? 0) / 100, quoteLines: (sb?.quote?.lines ?? []).map(l => `${l.role} | ${l.label} | ${l.quantity} x ${l.unitSatang / 100} = ${l.totalSatang / 100}`) };\ntill.off('response', onResp);\nawait till.getByTestId('payment-step').waitFor({ timeout: 30000 }); await till.waitForTimeout(2500);\nawait S.shot(till, '05d-settle-payment-step.png');\nconst back = till.getByTestId('payment-step').getByRole('button', { name: 'Back', exact: true });\nawait back.click(); await till.waitForTimeout(3000);\nconst body = S.flat(await till.locator('body').innerText());\nr.afterBack = { bill: body.match(/Party bill[^]*?Outstanding[^฿]*฿[0-9,]+/)?.[0]?.slice(0, 600) ?? null };\nconst buttons = [];\nfor (const b of await till.getByRole('button').all()) { const l = S.flat(await b.innerText().catch(() => '')); if (/Take balance|Fully paid|Resume settlement|Cancel settlement|Settle party/.test(l) && await b.isVisible()) buttons.push({ l, enabled: await b.isEnabled() }); }\nr.afterBack.buttons = buttons;\nawait till.mouse.wheel(0, -3000); await till.waitForTimeout(400);\nawait S.shot(till, '09a-till-desk-settlement-open-party-bill.png');\nS.receipt.reads.p5open = r;\nreturn r;\n",
 "steps/20x-inspect.js": "S.phase = '5: what the till shows after Confirm';\nconst till = S.pages.till.page;\nconst body = S.flat(await till.locator('body').innerText().catch(() => ''));\nconst dlg = S.flat(await till.getByRole('dialog').last().innerText().catch(() => ''));\nconst sale = S.settleSale ? await S.sale(S.settleSale) : null;\nconst party = (await S.party(S.p1)).body?.event?.party?.settlement ?? null;\nawait S.shot(till, 'zz-debug-after-confirm.png');\nreturn { settleSale: S.settleSale ?? null, locked: await till.getByRole('heading', { name: 'Locked', exact: true }).isVisible().catch(() => false), dialog: dlg.slice(0, 1200), body: body.slice(0, 600), sale: sale ? { status: sale.sale?.status, gross: sale.sale?.totals?.grossSatang ?? sale.sale?.grossSatang } : null, party, preview: S.receipt.reads.p5open ?? null };\n",
 "steps/21-phone-open-then-pay.js": "S.phase = '9/5: the phone page while the settlement is open; then Resume settlement on the desk and cash for the whole balance';\nconst phone = S.pages.phone.page, till = S.pages.till.page;\nconst r = {};\nawait S.unlock('phone');\nawait phone.goto(`/parties?party=${S.p1}`); await phone.waitForTimeout(4000);\nif (!/Party bill/.test(S.flat(await phone.locator('body').innerText()))) { await phone.goto('/parties'); await phone.waitForTimeout(3000); await phone.getByText(S.P1).first().click(); await phone.waitForTimeout(3500); }\nconst pb = S.flat(await phone.locator('body').innerText());\nr.phone = { header: pb.match(/ZZ TEST 906 party[^]{0,80}/)?.[0] ?? null, bill: pb.match(/Party bill[^]*?Outstanding[^฿]*฿[0-9,]+/)?.[0]?.slice(0, 500) ?? null, fullyPaidShown: /Fully paid/.test(pb), openRows: pb.match(/Settlement open[^A-Z]{0,30}/g) ?? null };\nconst pbtn = [];\nfor (const b of await phone.getByRole('button').all()) { const l = S.flat(await b.innerText().catch(() => '')); if (/Settlement open|Take balance|Fully paid|Resume/.test(l) && await b.isVisible()) pbtn.push({ l, enabled: await b.isEnabled() }); }\nr.phone.buttons = pbtn;\nawait phone.mouse.wheel(0, -3000); await phone.waitForTimeout(400);\nawait S.shot(phone, '09b-till-phone-settlement-open-header-and-bill.png');\nawait phone.mouse.wheel(0, 3000); await phone.waitForTimeout(500);\nawait S.shot(phone, '09c-till-phone-settlement-open-bottom.png');\n// pay the whole balance in cash on the desk\nawait S.unlock('till');\nawait S.openParty(till, S.p1, S.P1);\nconst resume = till.getByRole('button', { name: /^Resume settlement/ }).first();\nr.resumeLabel = S.flat(await resume.innerText());\nawait resume.click();\nawait till.getByTestId('payment-step').waitFor({ timeout: 30000 }); await till.waitForTimeout(2500);\nr.amountDue = await till.evaluate(() => { const h = [...document.querySelectorAll('h2')].find(x => x.textContent.trim() === 'Amount Due'); return h ? (h.nextElementSibling?.textContent ?? '').trim() : null; });\nawait till.getByRole('heading', { name: 'Cash', exact: true }).first().click();\nconst confirm = till.getByRole('button', { name: 'Confirm Payment Received', exact: true });\nawait S.expect(confirm).toBeEnabled({ timeout: 20000 });\nawait confirm.scrollIntoViewIfNeeded();\nawait S.shot(till, '05c-settle-cash-chosen.png');\nawait confirm.click();\nawait till.getByText(/Settled|Payment Successful/).first().waitFor({ timeout: 60000 });\nawait till.waitForTimeout(2500);\nr.done = S.flat(await till.getByRole('dialog').last().innerText().catch(() => '')).slice(0, 300);\nawait S.shot(till, '05d-settled.png');\nconst sale = await S.sale(S.settleSale);\nr.sale = { status: sale?.sale?.status ?? null, receipt: sale?.sale?.receiptNumber ?? null, gross: (sale?.sale?.totals?.grossSatang ?? sale?.sale?.grossSatang ?? 0) / 100,\n  lines: (sale?.lines ?? sale?.sale?.lines ?? []).map(l => `${l.label ?? l.name} | ${l.quantity} x ${(l.unitSatang ?? 0) / 100} = ${(l.grossSatang ?? l.totalSatang ?? 0) / 100}${l.taxCategory ? ' | ' + l.taxCategory : ''}`),\n  payments: (sale?.payments ?? sale?.tenders ?? []).map(p => `${p.method} ${(p.amountSatang ?? 0) / 100} ${p.status ?? ''}`),\n  printJobs: (sale?.printJobs ?? []).map(j => `${j.kind} ${j.role} ${j.status}`) };\nr.saleKeys = sale ? Object.keys(sale) : null;\nr.party = (await S.party(S.p1)).body?.event?.party?.settlement ?? null;\nS.receipt.reads.p5paid = r;\nreturn r;\n",
 "steps/22-refund.js": "S.phase = '5: the staging manager refunds the settlement whole from History; the party is as before settlement';\nconst r = {};\n// memory: one till context closed before the manager's opens\nconst ph = await S.signOutTill('phone');\nr.phoneSignOut = ph;\nconst mgr = await S.signIn('mgr', 'STAGING_MANAGER_PHONE', 'STAGING_MANAGER_PASSWORD', { width: 1680, height: 1050 });\nawait mgr.goto('/history'); await mgr.waitForTimeout(5000);\nconst sale0 = await S.sale(S.settleSale);\nconst rn = sale0?.sale?.receiptNumber ?? null;\nr.receipt = rn;\nawait mgr.evaluate((rn) => {\n  for (const b of document.querySelectorAll('div.space-y-2 > button.w-full.text-left')) {\n    const t = b.innerText.replace(/\\s+/g, ' ');\n    if ((rn && t.includes(rn)) || t.includes('Z90601-')) b.setAttribute('data-zz', 'mine'); else b.removeAttribute('data-zz');\n  }\n}, rn);\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..'), S.otherSales(page)];\nconst mine = mgr.locator('button[data-zz]');\nr.listed = [];\nfor (let i = 0; i < await mine.count(); i++) r.listed.push(S.flat(await mine.nth(i).innerText()).slice(0, 160));\nawait S.shot(mgr, '05e-history-list-settlement.png');\nawait mine.filter({ hasText: rn ?? 'Z90601-' }).first().click();\nawait mgr.waitForTimeout(3500);\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nr.detail = S.flat(await mgr.locator('body').innerText()).match(/(Paid|Refunded|Partly paid)[^]{0,900}/)?.[0]?.slice(0, 900) ?? null;\nawait S.shot(mgr, '05f-history-detail-settlement-lines.png', [], { fullPage: true });\nawait mgr.getByTestId('refund-sale').click();\nconst dialog = mgr.getByRole('dialog');\nawait dialog.waitFor();\nr.dialog = S.flat(await dialog.innerText()).slice(0, 500);\nawait dialog.getByRole('button', { name: 'Service recovery', exact: true }).click();\nawait dialog.locator('textarea').first().fill('ZZ TEST SCRUM-906 proof: refund the whole settlement');\nawait S.shot(mgr, '05g-manager-refund-whole.png');\nconst press = dialog.getByRole('button', { name: /^Refund ฿/ });\nr.press = S.flat(await press.innerText());\nconst resp = mgr.waitForResponse(rr => new URL(rr.url()).pathname === `/api/sales/${S.settleSale}/refunds` && rr.request().method() === 'POST', { timeout: 60000 });\nawait press.click();\nconst rr = await resp;\nconst rb = await rr.json().catch(() => null);\nawait mgr.waitForTimeout(3000);\nawait S.shot(mgr, '05h-history-detail-after-refund.png');\nconst sale = await S.sale(S.settleSale);\nr.refund = { status: rr.status(), amount: (rb?.refund?.amountSatang ?? 0) / 100, refundStatus: rb?.refundStatus ?? null, saleStatus: sale?.sale?.status ?? null, saleRefund: sale?.refundStatus ?? null };\nconst party = (await S.party(S.p1)).body;\nr.settlementAfter = party?.event?.party?.settlement ?? null;\n// the till's party page after the refund\nconst till = S.pages.till.page;\nawait S.unlock('till');\nawait S.openParty(till, S.p1, S.P1);\nconst btns = [];\nfor (const b of await till.getByRole('button').all()) { const l = S.flat(await b.innerText().catch(() => '')); if (/Take balance|Fully paid|Resume settlement|Cancel settlement|Settle party|Settled/.test(l) && await b.isVisible()) btns.push({ l, enabled: await b.isEnabled() }); }\nconst body = S.flat(await till.locator('body').innerText());\nr.partyPage = { buttons: btns, bill: body.match(/Party bill[^]*?Outstanding[^฿]*฿[0-9,]+/)?.[0]?.slice(0, 400) ?? null };\nawait till.mouse.wheel(0, -3000); await till.waitForTimeout(400);\nawait S.shot(till, '05i-party-page-after-refund-as-before.png');\nconst so = await S.signOutTill('mgr');\nr.mgrSignOut = so;\nS.receipt.reads.p5refund = r;\nreturn r;\n",
 "steps/22b-tax.js": "S.phase = '5: the sale read back (lines and tax), after the refund';\nconst s = await S.sale(S.settleSale);\nconst r = { status: s?.sale?.status, refundStatus: s?.refundStatus, refundable: (s?.refundableSatang ?? 0) / 100,\n  lines: (s?.lines ?? []).map(l => ({ label: l.label ?? l.name, qty: l.quantity, unit: (l.unitSatang ?? 0) / 100, gross: (l.grossSatang ?? 0) / 100, tax: l.taxCategory ?? l.taxArea ?? l.payload?.taxCategory ?? null })),\n  taxBreakdown: s?.taxBreakdown ?? null, refunds: (s?.refunds ?? []).map(x => ({ amount: (x.amountSatang ?? 0) / 100, method: x.method ?? x.tenderMethod ?? null, reason: x.reasonCode ?? x.reason ?? null })) };\nS.receipt.reads.p5sale = r;\nreturn r;\n",
 "steps/23-pdf.js": "S.phase = \"7: the BEO PDF of party 1 (the editor's Download PDF route; nothing printed)\";\nconst res = await S.app.ctx.request.get(`${S.APP}/api/events/${S.p1}/beo/pdf`, { timeout: 120000 });\nconst buf = await res.body();\nconst file = S.resolve(S.scratch, 'raw', 'beo-p1.pdf');\nS.writeFileSync(file, buf);\nS.writeFileSync(S.resolve(S.scratch, 'raw', 'names.txt'), S.needles().join('\\n'));\nconst r = { route: 'GET /api/events/:id/beo/pdf', status: res.status(), type: res.headers()['content-type'] ?? null, bytes: buf.length };\nS.receipt.reads.pdf = r;\nreturn r;\n",
 "steps/24-bigqty.js": "S.phase = '8: a very large quantity (250,000) on one BEO line of party 2 (the editor save route)';\nconst back0 = (await S.appCall('GET', `/events/${S.p2}/beo`)).body;\nconst kids = (back0?.kitchenPlan?.menus?.kids ?? []).map(l => l.itemName === 'ZZ TEST nuggets plate' ? { ...l, quantity: 250000 } : l);\nconst put = await S.appCall('PUT', `/events/${S.p2}/beo`, {\n  kitchenPlan: { foodRequired: true, setMenuEnabled: false, setMenuTemplateId: null, cakeMode: back0.kitchenPlan.cakeMode, cakeTime: back0.kitchenPlan.cakeTime, cakeNotes: back0.kitchenPlan.cakeNotes,\n    menus: { kids, adults: [], adultsDiffer: false, kidsFoodTime: back0.kitchenPlan.menus?.kidsFoodTime ?? '16:30', adultsFoodTime: '' } },\n});\nconst r = { put: put.status };\nconst back = (await S.appCall('GET', `/events/${S.p2}/beo`)).body;\nr.beoKids = (back?.kitchenPlan?.menus?.kids ?? []).map(l => `${l.itemName} x${l.quantity}`);\nr.beoBar = (back?.barPlan?.items ?? []).map(l => `${l.itemName} x${l.quantity}`);\nr.till = await S.tillRead(S.p2, 'p2-bigqty');\nconst desk = S.pages.till.page;\nawait S.unlock('till');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nawait S.openParty(desk, S.p2, S.P2);\nr.deskKitchen = await S.cardText(desk, 'Kitchen plan');\nr.deskBar = await S.cardText(desk, 'Bar plan');\nawait desk.mouse.wheel(0, -3000); await desk.waitForTimeout(400);\nawait S.shot(desk, '08a-till-desk-quantity-250000.png');\n// the BEO side of the same line\nawait S.openBeo(S.p2);\nawait S.openSection('accordion-kitchen-plan');\nawait S.appShot('08b-beo-quantity-250000.png', 'accordion-kitchen-plan', 'start');\nS.receipt.reads.p8 = r;\nreturn r;\n",
 "steps/25-package-only.js": "S.phase = '9: an ordinary party with only the package (no extra lines, no parent choice)';\nS.P3 = 'ZZ TEST 906 package only';\nconst ev = await S.appCall('POST', '/admin/events', { eventType: 'birthday', title: S.P3, branchId: S.APP_FLORESTA, eventDate: S.today, startTime: '18:00', endTime: '21:00', durationMinutes: 180, numChildren: 2, numAdults: 2, childName: 'ZZ TEST child three', status: 'upcoming' });\nS.assert.equal(ev.status, 201, 'party 3 created');\nS.p3 = ev.body.id;\nS.receipt.created.push({ kind: 'oto-app party', id: S.p3, title: S.P3 }); S.save();\nconst snap = await S.appCall('POST', `/beo/events/${S.p3}/package-snapshot`, { templateId: S.FLORESTA_PACKAGE });\nconst later = await S.appCall('PATCH', `/beo/events/${S.p3}/package-snapshot`, { slipsTime: '23:50' });\nconst r = { package: snap.status, slipsTimeMoved: later.status };\nr.till = await S.tillRead(S.p3, 'p3-package-only');\nconst p = (await S.party(S.p3)).body;\nr.planSetMenu = (p?.plan?.setMenu ?? []).map(m => `${m.origin ?? '-'} | ${m.name}${m.chosenOption ? ': ' + m.chosenOption : ''}${m.qty == null ? '' : ' x' + m.qty} | ${m.productCode ?? '-'}`);\nr.planBar = (p?.plan?.barItems ?? []).length;\nr.cake = p?.kitchenPlan?.cake ?? null;\nconst pv = await S.call('POST', `/parties/${S.p3}/settle/preview`, { branchId: S.branchId, stationId: S.station.id, kids: 2, adults: 2, socksGiven: 0, addOnIds: [], entertainmentIds: [] });\nr.settlePreview = { status: pv.status, lines: (pv.body?.quote?.lines ?? []).map(l => `${l.role} | ${l.label} | ${l.quantity} x ${l.unitSatang / 100} = ${l.totalSatang / 100}`), total: (pv.body?.quote?.totalSatang ?? 0) / 100 };\nconst desk = S.pages.till.page;\nawait S.unlock('till');\nS.inPlace = page => [page.getByLabel('Lock screen').locator('..')];\nawait S.openParty(desk, S.p3, S.P3);\nr.deskKitchen = await S.cardText(desk, 'Kitchen plan');\nr.deskHasBar = (await desk.locator('div.font-bold', { hasText: /^Bar plan$/ }).count()) > 0;\nawait desk.mouse.wheel(0, -3000); await desk.waitForTimeout(400);\nawait S.shot(desk, '09d-till-desk-package-only-party.png');\nS.receipt.reads.p9 = r;\nreturn r;\n",
 "steps/25b-bigqty-packaged.js": "S.phase = '8: 250,000 on a typed line of a party WITH a package (party 3): the plan stays readable and the settle preview answers';\nconst b0 = (await S.appCall('GET', `/events/${S.p3}/beo`)).body;\nconst kp0 = b0?.kitchenPlan ?? {};\nconst kids = [...(kp0.menus?.kids ?? []), { id: 'zz906-p3-big', itemName: 'ZZ TEST typo line', quantity: 250000, notes: '', included: false, price: 0 }];\nconst put = await S.appCall('PUT', `/events/${S.p3}/beo`, { kitchenPlan: { foodRequired: true, setMenuEnabled: kp0.setMenuEnabled ?? true, setMenuTemplateId: kp0.setMenuTemplateId ?? null, cakeMode: kp0.cakeMode ?? 'NONE', menus: { kids, adults: [], adultsDiffer: false, kidsFoodTime: '', adultsFoodTime: '' } } });\nconst r = { put: put.status };\nconst p = (await S.party(S.p3)).body;\nr.planStatus = p?.planStatus ?? null;\nr.planPresent = !!p?.plan;\nr.kitchenLines = (p?.kitchenPlan?.setMenu ?? []).map(m => `${m.name}${m.qty == null ? '' : ' x' + m.qty}`);\nconst pv = await S.call('POST', `/parties/${S.p3}/settle/preview`, { branchId: S.branchId, stationId: S.station.id, kids: 2, adults: 2, socksGiven: 0, addOnIds: [], entertainmentIds: [] });\nr.settlePreview = { status: pv.status, total: (pv.body?.quote?.totalSatang ?? 0) / 100, code: pv.body?.error?.code ?? null };\nconst desk = S.pages.till.page;\nawait S.unlock('till');\nawait S.openParty(desk, S.p3, S.P3);\nr.desk = (await S.cardText(desk, 'Kitchen plan')).match(/ZZ TEST typo line[^×]*×\\d+/)?.[0] ?? null;\nawait S.cardOf(desk, 'Kitchen plan').scrollIntoViewIfNeeded().catch(() => {});\nawait S.shot(desk, '08c-till-desk-packaged-party-quantity-250000.png', [], { element: S.cardOf(desk, 'Kitchen plan') });\nS.receipt.reads.p8packaged = r;\nreturn r;\n",
 "steps/26-station-back.js": "S.phase = \"4: the park's party slips station set back to none\";\nconst back = await S.call('PATCH', `/branches/${S.branchId}`, { partySlipsStationId: null });\nconst now = (await S.call('GET', '/branches')).body.branches.find(b => b.id === S.branchId).partySlipsStationId ?? null;\nif (back.status === 200 && now === null) S.stationNamed = false;\nconst r = { status: back.status, readBack: now, at: new Date().toISOString(), jobsAtTillWhileNamed: (await S.jobsAtTill(S.slipsFrom)).map(j => `${j.bangkok} ${j.role} ${j.status}`) };\nS.receipt.reads.stationBack = r;\nreturn r;\n",
 "steps/27-release-picture.js": "S.phase = '6: the release read back, drawn as a page (API answers only)';\nconst h = S.receipt.reads.health.at(-1);\nconst rel = S.receipt.reads.release.at(-1);\nconst p2 = S.receipt.reads.p2?.till;\nconst esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]);\nconst row = (k, v) => `<tr><td style=\"border:1px solid #bbb;padding:5px 9px;background:#f6f6f6;vertical-align:top\">${esc(k)}</td><td style=\"border:1px solid #bbb;padding:5px 9px\">${v}</td></tr>`;\nconst ctx = await S.browser.newContext({ viewport: { width: 1200, height: 800 } });\nconst page = await ctx.newPage();\nawait page.setContent(`<html><body style=\"font-family:Segoe UI,Arial;margin:0;padding:22px 26px;background:#fff;color:#111\">\n<h2 style=\"margin:0 0 6px\">SCRUM-906 point 6: the release, read back through the staging api (no database read)</h2>\n<p style=\"margin:2px 0 10px;color:#555\">oto-api-staging dep-dbqrjnbbc2fs73e80610 live at f1735975 from 13:11:38Z (20:11 Bangkok). Read at ${esc(S.bkk(rel.at))} Bangkok.</p>\n<table style=\"border-collapse:collapse;font-size:14px;width:100%\">\n${row('GET /api/ops/health: job:parties.slips', esc(JSON.stringify(h.job)) + '<br><b>No counts</b> (notCaughtUp, changesRebased) are in the answer: the register gives status, last run and outcome only.')}\n${row('Audit party.slips_schedule_start since 13:05Z', esc(rel.scheduleStart.total) + ' rows: ' + esc(rel.scheduleStart.entries.map(e => `${e.bangkok} ${e.branchIsFloresta ? 'Central Floresta' : 'the other park'} (startedAt ${e.after?.startedAt})`).join('; ')))}\n${row('Audit party.slips_rebase since 13:05Z', esc(rel.rebase.total) + ' row: ' + esc(rel.rebase.entries.map(e => `${e.bangkok} Central Floresta, a party printed before the release (stations ${e.after?.stations?.map(s => s.station + ' ' + s.source).join(', ')}), composer ${e.after?.composer}`).join('; ')) + ' (not this run\\'s party; nothing printed for it)')}\n${row('Audit party.slips_print since 13:05Z', esc(rel.print.total) + ' row: ' + esc(rel.print.entries.map(e => `${e.bangkok} trigger ${e.after?.trigger}`).join('; ')) + ' (this run\\'s own press on party 1)')}\n${row('Audit party.slips_change since 13:05Z', esc(rel.change.total) + ' rows: ' + esc(rel.change.entries.map(e => e.bangkok).join(', ')) + ' (this run\\'s own two BEO changes on party 1)')}\n${row('Kitchen and bar print jobs at Central Floresta since the api went live', esc(rel.parkKitchenBarJobsSinceApi.length) + ': ' + esc(rel.parkKitchenBarJobsSinceApi.map(j => j.bangkok + ' ' + j.kind).join(', ')) + ' (all at the ZZ TEST till, this run\\'s own)')}\n${row('Kitchen and bar print jobs at the other park since the api went live', esc(rel.otherParks.map(p => p.kitchenBarJobsSinceApi).join(', ')))}\n${row('Party 2 (no package, slip time 11:00, made 20:28)', esc(`slips ${JSON.stringify(p2?.slips)}`) + ': the schedule did not print it, with the ZZ TEST till named for party slips from 20:29:30 to 20:42:15 (not caught up)')}\n</table></body></html>`);\nawait page.screenshot({ path: S.resolve(S.out, '06a-release-readback.png'), fullPage: true });\nawait ctx.close();\nreturn 'ok';\n",
 "steps/28-p2-slips-now.js": "S.phase = '6: party 2 slips read again before clean-up';\nconst p = (await S.party(S.p2)).body;\nconst r = { at: new Date().toISOString(), slips: p?.slips ? { slipsTime: p.slips.slipsTime, station: p.slips.station?.name ?? null, records: (p.slips.records ?? []).map(x => `${x.station} run ${x.run} ${x.trigger} ${x.status}`) } : null,\n  printAuditP2: (await S.auditOf('party.slips_print', S.p2.toLowerCase())).length };\nS.receipt.reads.p2SlipsBeforeCleanup = r;\nreturn r;\n",
 "steps/30-cleanup.js": "S.phase = 'clean-up: everything this run made, each read back';\nconst done = {};\nconst clean = async (what, fn) => { try { done[what] = await fn(); } catch (e) { done[what] = { failed: String(e?.message ?? e).split('\\n')[0].slice(0, 300) }; } S.receipt.cleanup = done; S.save(); };\nawait clean('party slips station', async () => {\n  let now = (await S.call('GET', '/branches')).body.branches.find(b => b.id === S.branchId).partySlipsStationId ?? null;\n  if (now === S.station.id) { await S.call('PATCH', `/branches/${S.branchId}`, { partySlipsStationId: null }); now = (await S.call('GET', '/branches')).body.branches.find(b => b.id === S.branchId).partySlipsStationId ?? null; }\n  S.assert.equal(now, null); return { partySlipsStationId: now };\n});\nawait clean('the till sales', async () => {\n  const sales = await S.stationSales();\n  for (const s of sales) S.assert.equal(s.stationId, S.station.id);\n  for (const s of sales.filter(x => ['open', 'tendering'].includes(x.status))) S.assert.equal((await S.call('POST', `/sales/${s.id}/void`, { reason: 'ZZ TEST SCRUM-906 proof cleanup' })).status, 200);\n  const after = await S.stationSales();\n  return { sales: after.map(s => `${s.receiptNumber ?? 'no receipt'} ${s.status} ${(s.totals?.grossSatang ?? s.grossSatang ?? 0) / 100}`) };\n});\nfor (const [id, title] of [[S.p1, S.P1], [S.p2, S.P2], [S.p3, S.P3]]) {\n  if (!id) continue;\n  await clean(`party ${title}`, async () => {\n    S.assert.ok(/^ZZ TEST/.test(title), 'only ZZ TEST parties');\n    const del = await S.appCall('DELETE', `/admin/events/${id}`);\n    const app = await S.appCall('GET', `/admin/events/${id}`);\n    const beo = await S.appCall('GET', `/events/${id}/beo`);\n    const till = await S.party(id);\n    return { delete: del.status, appEvent: app.status, appBeo: beo.status, tillParty: till.status, tillCode: till.body?.error?.code ?? null };\n  });\n}\nawait clean('no ZZ TEST 906 party left', async () => {\n  const list = await S.appCall('GET', `/admin/events?range=all&includeArchived=true&branchId=${S.APP_FLORESTA}`);\n  const left = Array.isArray(list.body) ? list.body.filter(e => /ZZ TEST 906/.test(String(e.title || ''))).length : null;\n  const tillToday = ((await S.call('GET', `/events?branchId=${S.branchId}&type=party`)).body?.events ?? []).filter(e => /ZZ TEST 906/.test(e.title)).length;\n  return { appListStatus: list.status, leftInApp: left, leftOnTillToday: tillToday };\n});\nawait clean('the ZZ TEST till', async () => {\n  S.assert.equal((await S.call('PATCH', `/stations/${S.station.id}`, { devices: [] })).status, 200);\n  const del = await S.call('DELETE', `/stations/${S.station.id}`);\n  const row = (await S.call('GET', `/branches/${S.branchId}/stations?includeArchived=true`)).body.stations.find(s => s.id === S.station.id);\n  return { delete: del.status, archived: !!row?.archived, devices: row?.devices?.length ?? null };\n});\nawait clean('the ZZ TEST printers', async () => {\n  const out = [];\n  for (const [role, d] of Object.entries(S.devices)) {\n    const r = await S.call('DELETE', `/devices/${d.id}`);\n    out.push(`${role} ${r.status} stillAssigned ${r.body?.stillAssignedTo?.length ?? '-'}`);\n  }\n  const after = (await S.call('GET', `/boxes/${S.box.id}/devices?includeArchived=true`)).body.devices.filter(x => Object.values(S.devices).some(d => d.id === x.id));\n  return { deletes: out, allArchived: after.length === Object.keys(S.devices).length && after.every(x => x.archived) };\n});\nreturn done;\n",
 "steps/31-signout.js": "S.phase = 'sign-out: every session of this run, each read back';\nconst out = { at: new Date().toISOString() };\nfor (const label of Object.keys(S.pages)) out[label] = await S.signOutTill(label);\nif (S.parentCtx) { await S.parentCtx.close().catch(() => {}); out.parentLinkPage = 'closed (public page, no session)'; }\nif (S.app) {\n  const c = S.app.ctx;\n  const lo = await c.request.post(S.APP + '/api/logout', { headers: { 'Idempotency-Key': S.randomUUID() } }).catch(() => null);\n  const so = await c.request.post(S.LAUNCHER + '/api/auth/sign-out', { data: {}, headers: { 'Idempotency-Key': S.randomUUID() } }).catch(() => null);\n  out.otoApp = { appLogout: lo?.status() ?? null, launcherSignOut: so?.status() ?? null, appUserAfter: (await c.request.get(S.APP + '/api/user').catch(() => null))?.status() ?? null, launcherMeAfter: (await c.request.get(S.LAUNCHER + '/api/me').catch(() => null))?.status() ?? null };\n  await c.close().catch(() => {});\n  S.app = null;\n}\nconst so = await S.admin.post('/api/auth/sign-out', { headers: { 'idempotency-key': S.randomUUID() } });\nout.platformAdmin = { signOut: so.status(), meAfter: (await S.admin.get('/api/me')).status() };\nS.receipt.cleanup.signOut = out;\nS.receipt.finishedAt = new Date().toISOString();\nreturn out;\n"
};
const dir = process.argv[2];
if (!dir) { console.log(Object.keys(FILES).join('\n')); process.exit(0); }
for (const [name, text] of Object.entries(FILES)) { const f = resolve(dir, name); mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, text); }
console.log('written', Object.keys(FILES).length, 'files to', dir);
